const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "sqlite",
  "inlineSchema": "// ═══════════════════════════════════════════════════════════════\n// AGENT — T09 Agent Runtime（Slice 2：持久化）\n//\n// 对齐：AC-08（注入不得改变权限 / 泄露资料 / 绕过审批）、AC-20（**每次调用可归因**）\n//\n// 设计约束（继承 outcome.prisma / billing.prisma 的同一套）：\n//   1. **纯新增** —— 本文件不改动既有模型的任何列语义，可独立上线（零停机、零回归）。\n//   2. **方言无关** —— 不含任何 `@db.*` 原生类型标注。\n//   3. **软引用优先** —— `requestedBy` / `actorId` / `subjectLabel` 都不建 FK：\n//      用户注销后，**谁批准过什么**必须仍然可查（审计的意义就在于此）。\n//      只有 `organizationId` 与 `AgentCall.runId` / `AgentApproval.runId` 建真 FK。\n//\n// ── 与 `src/lib/agent/`（Slice 1 纯内核）的关系 ──────────────────────\n//   内核**不 import 本文件的任何东西**（它连 Prisma 都不 import —— 见\n//   `scripts/check-agent-invariants.mjs` 的 A2）。本文件是**租户服务层**的存储形态，\n//   服务层在 `src/lib/agents/`。\n//   🔴 目录边界**就是**执法点：`src/lib/agent`（单数）＝无 IO 的内核；\n//      `src/lib/agents`（复数）＝允许碰 DB 的服务层。把这两件事混进一个目录，\n//      A1/A2 门禁立刻失效，而\"内核无 IO\"这条保证会**静默**退化成口头约定。\n//\n// ── 为什么 `AgentRun.status` **是列**（而不是像 `BillingEvent` 那样不落列）──\n//   T08 在 billing.prisma 里立过\"状态是派生值，不落列\"，其判据是：\n//   该状态**永远只由事件集派生**、且**不会被下推成 SQL 谓词**。\n//   本表不满足该判据的第二条：「待我审批的运行」是一个**必须下推**的查询\n//   （`WHERE status IN ('AWAITING_APPROVAL','DEGRADED')`）。\n//   不落列就只能\"取最近 N 条 → 应用层派生\"，那会踩 T07 立下的\n//   「派生过滤无法下推 SQL 时的诚实口径」（SCAN_LIMIT）—— 列表页的**总数**会失真。\n//   ⇒ 落列，但配两条硬约束把\"第二个事实来源\"的风险压住：\n//     ① `status` **只**经 `src/lib/agents/runs.ts` 的 `transitionRun()` 修改，\n//        该函数在执行 UPDATE 前**必须**先过 `approval.ts` 的真相表断言；\n//     ② 终态一致性有**可复跑的对账断言**（见 `scripts/connection/migrate.mjs` 的\n//        C6 段 + `tests/agents/approval-consistency.test.ts`）：`status='APPROVED'|'REJECTED'`\n//        的运行**必须**有一条对应的 `AgentApproval` 行。\n//\n// ── 为什么 `AgentCall` 是独立表（而不是 AgentRun 上的几个列）──\n//   一次运行可以有**多次**模型调用（重试 / 降级路径 / 将来的多步技能），\n//   而 AC-20 要求\"**每次调用**可归因\"。挤进 AgentRun 的列就会把\n//   \"最后一次调用\"当成\"这次运行花的钱\" —— 重试场景下金额会**静默少算**。\n// ═══════════════════════════════════════════════════════════════\n\n/// 运行状态。**必须与 `src/lib/agent/types.ts` 的 `AGENT_RUN_STATUSES` 逐字一致**\n/// （有测试守着：`tests/agents/schema-drift.test.ts`）。\n///\n/// ⚠️ 为什么用 Prisma enum 而不是裸 `String`：既有的 connection.prisma / billing.prisma\n/// 都这么做；SQLite 下枚举落为 TEXT，不引入数据库方言差异。\n/// 代价是\"TS 与 Prisma 两处清单\"，因此**必须**有漂移检测 —— 否则新增一个状态时\n/// 只在 TS 加了，写入会在运行期才炸。\nenum AgentRunStatus {\n  PROPOSED\n  AWAITING_APPROVAL\n  APPROVED\n  REJECTED\n  EXECUTED\n  DEGRADED\n  BLOCKED_QUOTA\n  FAILED\n}\n\n/// 风险级。与 `types.ts` 的 `RISK_LEVELS` 逐字一致。\nenum AgentRiskLevel {\n  LOW\n  MEDIUM\n  HIGH\n}\n\n/// 模型提供方种类。与 `types.ts` 的 `PROVIDER_KINDS` 逐字一致。\n/// 🔴 `RULES` = **根本没调模型**（规则式兜底）—— 把它记进账本，\n///    才能使\"降级率\"可复算，而不是只能靠读日志。\nenum AgentProviderKind {\n  OPENAI\n  // WorkBuddy 云端算力（免密钥 · OpenAI 兼容协议 · 只支持流式）\n  WORKBUDDY\n  STUB\n  RULES\n}\n\n/// 人工裁决结果。**只有两种终局**：批准 / 驳回。\n/// 🔴 这里**没有** `EXECUTED` —— 裁决与执行是两件事（见文件末「执行不在本切片」）。\nenum AgentApprovalDecision {\n  APPROVED\n  REJECTED\n}\n\n/// 执行效果的种类。**必须与 `src/lib/agent/execution.ts` 的 `EXECUTION_KINDS` 逐字一致**\n/// （有漂移守卫：`tests/agents/schema-drift.test.ts`）。\n///\n/// 🔴 为什么只有 `RECEIPT`：本切片落地的执行效果是**内部回执**（站内信给发起人）。\n///    对外送达（介绍真发给对手方）需要**收件人身份** + T05 的 `discloseSubject()` 出口，\n///    属下一片。把\"当前只有哪一种\"写成枚举，而不是让 `kind` 变成自由字符串 ——\n///    后者会让\"某天悄悄多出一种效果\"没有任何东西会报错。\nenum AgentExecutionKind {\n  RECEIPT\n}\n\n/// 一次 Agent 运行（提案的持久形态）。\n///\n/// 🔴 本表**不含**任何主体档案数据：只有 `subjectLabel` 这类**标签**。\n///    真实披露要等接线，且必须经 `discloseSubject()` 投影后再进 prompt（AC-03）。\nmodel AgentRun {\n  id String @id @default(cuid())\n\n  /// 租户谓词。**不可省** —— 所有查询都以它为首要条件（T01 铁律）。\n  organizationId String\n\n  /// 技能键（`INTENT_EXTRACTION` / `INTRO_DRAFT` / `COORDINATION_ADVICE`）。\n  skill String\n\n  /// 当前状态。创建时落初值，此后只经 `decideAgentRun()` 修改（见文件头）。\n  status AgentRunStatus\n\n  /// 该技能的风险级（快照）。落库理由：以后调整技能风险级，\n  /// 历史运行的**当时**风险级不应被追溯修改。\n  risk AgentRiskLevel\n\n  /// 是否必须人工批准才能执行（含\"因注入信号而升级\"的情形）。\n  requiresApproval Boolean @default(false)\n\n  /// 发起人（**软引用**，无 FK）：用户注销后\"谁批准过什么\"仍须可查。\n  requestedBy String\n\n  /// 目标的对象标签（**不是档案**）。Slice 2 只存这个，不存任何字段值。\n  subjectLabel String?\n\n  /// 用户原始目标文本。属于**不可信输入**，落库仅为可追溯。\n  goal String\n\n  /// 经 zod 校验后的结构化产出（JSON 文本）。**这才是可渲染的那一份**。\n  /// 契约拒绝时为 null（`rawText` 可能仍在 —— 那是审计用的证据）。\n  proposalJson String?\n\n  /// 模型原始文本。**仅供审计/调试，永不进 DTO、永不渲染**。\n  /// 留着它的唯一理由：当契约拒绝了产出时，能回答\"模型到底说了什么\"。\n  rawText String?\n\n  /// 面向用户的说明（降级原因 / 注入升级说明 / 失败原因）。\n  reason String?\n\n  /// 降级/失败原因码（`DegradeReason`）。成功为 null。\n  degradeCode String?\n\n  /// 本次运行最终采用的提供方种类。\n  providerKind AgentProviderKind\n\n  /// 注入信号（JSON 数组）。**只作告警/升级审批的旁证**，不是放行判据。\n  injectionSignals String?\n\n  /// 本次运行**全部调用**的成本合计（微分）。冗余但刻意：\n  /// 列表页/用量页要按运行聚合，逐条 `JOIN AgentCall` 会随历史增长变慢。\n  /// ⚠️ 它**可以**与 `AgentCall` 不一致（写入非原子）→ 由 C6 的对账断言与\n  /// `tests/agents/*` 的一致性用例守着；不允许出现\"没人发现的不一致\"。\n  costMicroCents Int @default(0)\n\n  /// 幂等键：同一业务动作只产生一次运行。作用域 = `(organizationId, dedupeKey)`。\n  dedupeKey String\n\n  /// 产生本次运行的**请求体指纹**。理由同 `BillingEvent.requestHash`：\n  /// 唯一约束只能保证\"不重复\"，保证不了\"同一把键没被复用于另一个意图\"。\n  requestHash String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  organization Organization    @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  calls        AgentCall[]\n  approval     AgentApproval?\n  execution    AgentExecution?\n\n  /// Slice 6 · 对外送达的目标（**创建时**落库；决定权在服务层，不在批次里）。\n  deliveryTarget AgentDeliveryTarget?\n\n  @@unique([organizationId, dedupeKey])\n  @@index([organizationId, status])\n  @@index([organizationId, createdAt])\n  @@index([organizationId, skill])\n}\n\n/// 单次模型调用（或规则式兜底）的**归因记录** —— AC-20 的落点。\n///\n/// 🔴 失败的调用**也记**：否则\"失败不花钱\"这个假设永远没人验证过。\nmodel AgentCall {\n  id String @id @default(cuid())\n\n  /// 租户谓词。**不可省**（虽然是冗余的 —— run 已经带租户；但本仓的铁律是\n  /// \"每条账都要能独立按租户查询\"，冗余换掉一次 JOIN 与一类越权风险）。\n  organizationId String\n\n  runId String\n\n  /// 本次运行内的序号（从 1 开始）。`(runId, seq)` 唯一 ⇒ 重放不会插出重复行。\n  seq Int\n\n  skill String\n\n  providerKind AgentProviderKind\n\n  risk AgentRiskLevel\n\n  /// 是否为\"高成本\"调用（AC-20「限额触发时停止高成本任务」的判定对象）。\n  highCost Boolean\n\n  /// 调用是否成功。失败也入账。\n  ok Boolean\n\n  inputTokens  Int @default(0)\n  outputTokens Int @default(0)\n\n  /// 本次调用的成本（**微分**，整数 —— 与 `cost.ts` 同口径：1 分 = 1e6 微分）。\n  /// 用整数而非浮点分，是因为浮点累加会让\"对账\"变成\"看运气\"。\n  microCents Int @default(0)\n\n  /// 调用发生时刻（**由我们写入**）。注意与 `createdAt` 的区别：\n  /// 前者是业务时间（测试可注入），后者是行落库时间。\n  at DateTime\n\n  createdAt DateTime @default(now())\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  run          AgentRun     @relation(fields: [runId], references: [id], onDelete: Cascade)\n\n  @@unique([runId, seq])\n  @@index([organizationId, at])\n  @@index([organizationId, skill])\n  @@index([organizationId, highCost])\n}\n\n/// 人工裁决（**只增不改**的事件）。\n///\n/// 与 `AgentRun.status` 的分工：本表回答\"**谁在何时批了什么**\"（审计），\n/// `status` 回答\"现在能不能执行\"（查询）。两者的不一致由一致性断言守住。\nmodel AgentApproval {\n  id String @id @default(cuid())\n\n  organizationId String\n\n  runId String\n\n  decision AgentApprovalDecision\n\n  /// 裁决人（**软引用**，无 FK）。\n  actorId String?\n\n  /// 裁决时该人的租户角色（快照）。落库理由同 `AgentRun.risk`：\n  /// 以后改了角色能力矩阵，也不该改写历史裁决的**当时**依据。\n  deciderRole String\n\n  /// 裁决备注（驳回时尤其重要 —— \"为什么不行\"是要给人看的）。\n  note String?\n\n  decidedAt DateTime @default(now())\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  run          AgentRun     @relation(fields: [runId], references: [id], onDelete: Cascade)\n\n  /// 一次运行只允许**一条**终局裁决（不可改判 —— 要推翻就重新发起一次运行）。\n  @@unique([runId])\n  @@index([organizationId, decidedAt])\n  @@index([organizationId, decision])\n}\n\n/// 一次**执行**的记录 —— \"这条运行真的产生了副作用\"的证据（Slice 4）。\n///\n/// 🔴 为什么是**独立表**而不是 `AgentRun` 上的几个列（`executedAt` / `executionRef`）：\n///   1. `scripts/connection/migrate.mjs` 的批次机制**只支持 `CREATE TABLE/INDEX IF NOT EXISTS`**，\n///      没有 `ALTER TABLE` 形态（文件头约束 1：不改动既有表的任何列）。\n///      给既有表加列会把这个\"纯新增\"的迁移纪律破掉 —— 而上线期间破掉它，代价是停机。\n///   2. **只增不改**：执行是事件。列会被覆写（重试、误改），事件不会 ——\n///      与 `AgentApproval` 同一取向。`@@unique([runId])` 让\"一次运行只执行一次\"\n///      成为**库级**保证，而不是靠调用方自觉。\n///   3. `AgentRun.executedAt` 这列**刻意不存在**（DDL 反向断言守着）：执行时间属于执行记录。\n///\n/// ⚠️ `recipientId` / `actorId` / `deliveryId` 都是**软引用**（无 FK）：\n///    用户注销后\"这条运行执行给过谁、由谁执行\"仍须可查（与 `requestedBy` 同一理由）。\nmodel AgentExecution {\n  id String @id @default(cuid())\n\n  /// 租户谓词。**不可省**（T01 铁律）。\n  organizationId String\n\n  /// 被执行的运行。**强 FK + 唯一**：一条运行最多一条执行记录。\n  runId String\n\n  kind AgentExecutionKind\n\n  /// 实际投递渠道。与 T06 的 `NotificationChannel` 取值域一致（枚举复用，非新造）。\n  channel NotificationChannel\n\n  /// 收件人（**服务端决定**，不接受调用方指定）。两种来源，都由计划决定：\n  ///   - 计划 `recipient = 'REQUESTER'` → `AgentRun.requestedBy`（内部回执）；\n  ///   - 计划 `recipient = 'TARGET'`（Slice 6 起）→ `AgentDeliveryTarget.targetUserId`\n  ///     （**创建时**就固定、并被那次批准覆盖的那个身份）。\n  recipientId String\n\n  /// T06 投递归宿的 `NotificationDelivery.id`（软引用）—— 执行与投递留痕的挂钩点。\n  deliveryId String?\n\n  /// 投递结果状态快照（`SENT` / `CAPTURED` / `FAILED`）。冗余但刻意：\n  /// 投递记录是审计面，\"这次执行当时是什么结果\"不该依赖对另一张表的实时 JOIN。\n  deliveryStatus String\n\n  /// 执行人（软引用）。与发起人**分开记**：将来若允许他人代为执行，二者会不同。\n  actorId String?\n\n  /// 业务时间（测试可注入），与 `createdAt`（落库时间）分开 —— 同 `AgentCall.at` 的理由。\n  executedAt DateTime\n\n  createdAt DateTime @default(now())\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  run          AgentRun     @relation(fields: [runId], references: [id], onDelete: Cascade)\n\n  /// 一次运行只允许**一条**执行记录 ⇒ 库级幂等。并发下第二条插入撞唯一键，\n  /// 服务层据此读回胜者（而不是把\"重复执行\"变成 500）。\n  @@unique([runId])\n  @@index([organizationId, executedAt])\n  @@index([organizationId, channel])\n}\n\n// ── 执行：Slice 4 已接线（**唯一写入点**是 `src/lib/agents/executor.ts`）────\n// `AgentRunStatus.EXECUTED` 现在可达，但**只有一条路径**能到达它：\n//   服务端重判能力（`agent.execute`）→ 读回裁决行 → `planExecution()` 放行\n//   → 经 T06 的统一投递出口产生副作用并留痕 → 同一个事务里写 `status='EXECUTED'` + 本表的执行行。\n// 🔴 \"唯一写入点\"由 `tests/agents/execution-gated.test.ts` 的**静态断言**守着\n//    （服务层 + 路由层源码里 `EXECUTED` 字面量只允许出现在 `executor.ts`）。\n// 一致性由 `scripts/connection/migrate.mjs` 的 C7 段断言守着：\n//   ① `status='EXECUTED'` ⇒ 恰有一条 `AgentExecution`；\n//   ② `AgentExecution` 行的 run 必须是 `EXECUTED`。\n\n/// 一次**对外送达**的目标（Slice 6）—— \"这条产出送给谁\"的**创建时**事实。\n///\n/// 🔴 为什么是独立表而不是 `AgentRun.targetUserId` 列：本仓迁移机制只支持\n///    `CREATE TABLE/INDEX IF NOT EXISTS`（见 `scripts/connection/migrate.mjs` 文件头约束 1），\n///    给既有表加列会破掉\"纯新增\"这条纪律。独立成表还顺带拿到\n///    `@@unique([runId])` 的库级保证：**一条运行最多一个送达目标**。\n///\n/// 🔴 为什么必须在**创建时**落库、执行时**不补**：\n///    若执行时才由调用方传入收件人，就等于允许\"批准的是 A、发出去的是 B\"——\n///    审批会退化成橡皮图章。这里存的是**那次批准覆盖的那个身份**。\n///\n/// `targetUserId` / `intentId` 是**软引用**（无 FK）：用户注销、意图被删之后，\n/// \"这条运行当时打算送给谁、依据哪份披露\"仍须可查（与 `AgentRun.requestedBy` 同一理由）。\nmodel AgentDeliveryTarget {\n  id String @id @default(cuid())\n\n  /// 租户谓词。**不可省**（T01 铁律）。\n  organizationId String\n\n  /// 被送达的运行。**强 FK + 唯一**：一条运行最多一个送达目标。\n  runId String\n\n  /// 目标身份（对手方）。**创建时**由服务端校验并固定\n  /// （须与披露依据同属一个任务、且仍在参与 —— 见 `delivery-target.ts`）。\n  targetUserId String\n\n  /// 披露依据：**发起人自己**的 `SocialIntent.id`。执行时用它读回**当时生效**的披露表\n  /// —— T05「撤销即刻生效」在投递侧的落点。\n  intentId String\n\n  /// 送达档位（T05 的外部档位；当前恒为 `COUNTERPARTY`）。\n  /// 落列而不写死：审计要能读出\"当时是按哪一档送的\"。\n  audience String\n\n  /// 创建那一刻该受众可见的字段键（JSON 文本数组）—— **快照**。\n  /// 执行时用它判\"授权是否被收窄\"（内核 `planOutboundDelivery()`）。\n  /// 空数组存 null（与 `discloseSubject` 的\"空即不存在\"同一取向）。\n  authorizedFieldKeys String?\n\n  createdAt DateTime @default(now())\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  run          AgentRun     @relation(fields: [runId], references: [id], onDelete: Cascade)\n\n  /// 一条运行最多一个送达目标 ⇒ 库级幂等（并发下第二条撞唯一键）。\n  @@unique([runId])\n  @@index([organizationId, targetUserId])\n  @@index([organizationId, createdAt])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// BILLING — T08 组织级用量计费（Slice 3）\n//\n// 对齐：AC-21（**使用量可复算**；退款/失败/升级/降级**状态一致**）\n//\n// 设计约束（继承 outcome.prisma / tenancy.prisma 的同一套）：\n//   1. **纯新增** —— 本文件不改动既有模型的任何列语义，可独立上线（零停机、零回归）。\n//   2. **方言无关** —— 不含任何 `@db.*` 原生类型标注。\n//   3. **软引用优先** —— 账是历史。删掉一个提案/成果，不该抹掉\"这个月用了 5 次介绍\"。\n//   4. 🔴 **不复用 core.prisma 的 `Subscription` / `Payment`** —— 见下。\n//   5. 🔴 **状态是派生值，不是可写的列** —— 见下。\n//\n// ── 为什么不复用 `Subscription` / `Payment` ──────────────────────────\n//   它们面向**个人 B2C**（`userId` + Stripe + 会员权益），而本域是**组织级用量计费**\n//   （`organizationId` + Creem + 计量单位）。混用有三种污染：\n//     ① 语义污染：「这个用户是不是会员」这条既有查询会**悄悄包含社群订阅**；\n//     ② 网关污染：`stripeCustomerId` / `stripePriceId` 是 `@unique` 列，混入 Creem\n//        数据会迫使写空值，此后无法区分\"没订阅\"与\"非 Stripe 订阅\"；\n//     ③ 回滚污染：独立域意味着 C5 可整批 `rollback`（逆序 DROP），不触碰既有表。\n//\n// ── 为什么状态不落列（与 Slice 1 的 `Outcome.verificationLevel` 同取向）──\n//   `verificationLevel` 落列是因为它要被 SQL 计数（`WHERE verificationLevel IN (...)`）\n//   —— 那是一个**已知会被下推**的查询谓词。本域不同：订阅方案与账单状态只在\n//   「读当前状态」时被用到，且**永远由事件集派生**（`deriveSubscriptionState`）。\n//   落一个 `status` 列就等于造了第二个事实来源，它迟早与事件集不一致，\n//   而且不一致的那一刻没有任何东西会报错。⇒ **不落列**，读时派生。\n//\n// ── 事件溯源的两条硬约束 ────────────────────────────────────────────\n//   ① **只增不改**：想撤销一次确认就再记一条相反语义的事件，绝不 UPDATE 历史。\n//      否则\"这单当时到底成没成、退没退款\"永远无法回溯（AC-21 的全部意义）。\n//   ② **非法迁移必须在写入前被拒**：例如 `REFUNDED → SUCCEEDED` 必须失败。\n//      判据在纯内核里（`src/lib/billing/subscription.ts`），服务层写入前先过一遍。\n// ═══════════════════════════════════════════════════════════════\n\n/// 计费单元。\n///\n/// 🔴 与 `src/lib/outcome/metrics.ts` 的 `MetricUnit` **刻意同源** ——\n/// 用量账与商业指标必须是同一件事的两种视图。若两处各定义一套，\n/// \"介绍 3 次\"会在报表里变成两个数（AC-16 与 AC-21 会同时崩），\n/// 而**不会报任何错**。枚举顺序也保持一致，便于对账脚本按下标对齐。\nenum UsageUnit {\n  PROPOSAL // 发起一次连接提案\n  INTRODUCTION // 完成一次介绍（提案进入已介绍）\n  OUTCOME // 上报一份成果\n  VERIFICATION // 一份成果被核验（**按\"已被核验的成果数\"计，不是按核验记录条数** —— 幂等重放不该重复计费）\n}\n\n/// 订阅方案（组织级）。`FREE` **刻意不在枚举里** —— 见 `EffectivePlan`：\n/// \"没有订阅\"不是一种订阅，用 `null` 表达比用一个假的 `FREE` 行更诚实。\nenum BillingPlan {\n  STARTER\n  GROWTH\n  SCALE\n}\n\n/// 计费事件类型（事件溯源的**唯一**写入面）。\n///\n/// 命名规范 `<主语>_<动作>`，与 `TenantAuditEvent.eventType` 同名风格。\nenum BillingEventType {\n  SUBSCRIPTION_STARTED // 开通（方案由 `plan` 给出）\n  PLAN_CHANGED // 升/降级（方案由 `plan` 给出；升还是降**由纯内核按方案序推导**）\n  SUBSCRIPTION_CANCELED // 退订（退订后不可再收新款项，除非重新 STARTED）\n  CHARGE_CREATED // 一次支付尝试：进入 PENDING（`chargeId` 必填）\n  CHARGE_SUCCEEDED // 该次尝试成功\n  CHARGE_FAILED // 该次尝试失败（`reason` 必填 —— 失败的**原因**是运营要看的）\n  CHARGE_REFUNDED // 对该次成功尝试退款（终态）\n}\n\n/// 一笔支付尝试的**网关侧状态**（保存到事件上的快照）。\n///\n/// 🔴 `CAPTURED` 与 `SUCCEEDED` **必须分开**（与 `NotificationDeliveryStatus` 同一铁律）：\n///   前者是\"沙箱捕获了要发出去的请求\"，后者是\"真实网关已受理\"。\n///   把沙箱写成 SUCCEEDED 就是虚报外部服务已接通\n///   （主指令：「没有真实凭据的流程只能标记 MOCKED / BLOCKED，不能标记 PASSED」）。\nenum BillingGatewayStatus {\n  CAPTURED // 沙箱捕获（无 Creem 凭据）：记录\"要发什么\"，不冒充已扣款\n  SUCCEEDED // 真实网关受理（provider 回执落 `providerRef`）\n  FAILED\n}\n\n/// 计费事件（**不可变日志**）。当前方案 / 状态 / 每笔款项的生命周期全部由它派生。\nmodel BillingEvent {\n  id String @id @default(cuid())\n\n  /// 租户谓词。**不可省** —— 所有查询都以它为首要条件（T01 铁律）。\n  organizationId String\n\n  type BillingEventType\n\n  /// 目标方案。`SUBSCRIPTION_STARTED` / `PLAN_CHANGED` 必填，其余为 null。\n  plan BillingPlan?\n\n  /// 款项关联 id（**软引用**，无 FK）。同一笔尝试的 CREATED/SUCCEEDED/REFUNDED 共用它。\n  /// 由服务层生成；`CHARGE_*` 事件必填。\n  chargeId String?\n\n  /// 金额（**分**，整数 —— 避免浮点求和误差，与 `metrics.ts` 的 `unitCostsCents` 同口径）。\n  amountCents Int?\n\n  /// 币种（ISO 4217）。\n  currency String @default(\"USD\")\n\n  /// 网关回执引用。**不进 DTO**。\n  /// 沙箱语义下这里是**构造出来的请求指纹** —— 见 `src/lib/billing/creem.ts`。\n  providerRef String?\n\n  /// 本次尝试的网关侧状态快照。沙箱捕获时为 `CAPTURED`。\n  gatewayStatus BillingGatewayStatus?\n\n  /// 失败/退订的原因（`CHARGE_FAILED` / `SUBSCRIPTION_CANCELED` 必填 —— 原因是要给人看的）。\n  reason String?\n\n  /// 操作人（软引用，**不进 DTO**）：退款/退订这类管理动作要留痕。\n  actorId String?\n\n  /// 幂等键：同一业务动作只入账一次。唯一性作用域 = `(organizationId, dedupeKey)`。\n  /// ⚠️ 与 `IdempotencyRecord` **刻意并存**：后者作用在 HTTP 层（同键同体 → 回放首次结果），\n  /// 本字段作用在**账本层**（即使没有 HTTP 幂等头，账也不会重复）。\n  dedupeKey String\n\n  /// 产生本事件的**请求体指纹**（由调用方算好传入）。\n  ///\n  /// 🔴 为什么账本要自带它：`dedupeKey` 唯一约束只能保证\"不重复\"，**保证不了**\n  /// \"同一个键没有被复用于另一个意图\"。后者更危险 —— 调用方拿着旧键发新动作，\n  /// 若只按唯一约束处理就会**静默返回旧事件**，而调用方以为新动作生效了。\n  /// 有了指纹，服务层可以在命中时比对：**相同 → 回放（replayed）**、\n  /// **不同 → 409**（与 `src/lib/connection/idempotency.ts` 的语义逐字一致）。\n  /// 放在账本里而不是只放在 HTTP 层，是因为脚本/回填也必须受同一保护。\n  requestHash String?\n\n  /// 业务发生时间。**由我们写入**（格式统一为 Prisma 的 `...+00:00`），\n  /// 因此本域可以做**时段窗口**统计 —— 这正是 `metrics.ts` 口径 2 把时段留到\n  /// 本切片的原因：那边的 `introducedAt` 是历史遗留的混格式列，范围比较会静默错算。\n  occurredAt DateTime\n\n  createdAt DateTime @default(now())\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, dedupeKey])\n  @@index([organizationId, occurredAt])\n  @@index([organizationId, type])\n  @@index([organizationId, chargeId])\n}\n\n/// 用量记录（**只增不改**的账）。\n///\n/// 与 `src/lib/outcome/metrics.ts` 的关系（两者都对，但回答不同的问题）：\n///   - 指标（Slice 2）是**当前状态快照** —— \"现在有多少碳案双方同意\"；\n///   - 用量账（本表）是**历史流水** —— \"这个月真实发生了多少次介绍\"。\n///   二者在\"提案被撤销\"这类场景下会**故意**不同：撤销不退款，账不动。\n///   这正是不能用一条 SQL 从现状反推账单的原因，也是本表存在的理由。\nmodel UsageRecord {\n  id String @id @default(cuid())\n\n  /// 租户谓词。**不可省**。\n  organizationId String\n\n  unit UsageUnit\n\n  /// 数量。目前恒为 1（一条业务事实 = 一次用量），保留字段是为了将来\n  /// \"一次介绍覆盖 N 位成员\"这类批量单元不必改表。\n  quantity Int @default(1)\n\n  /// 业务发生时间。**由我们写入**（统一格式），供审计与排序。\n  occurredAt DateTime\n\n  /// 🔴 **计费期次**（`YYYY-MM`，UTC 自然月）。归集与限额都按它分组。\n  ///\n  /// 为什么不让对账脚本去 `WHERE occurredAt >= ? AND occurredAt < ?`：\n  /// 库里的 DateTime 是 TEXT，本项目**已经踩过**\"多来源格式混排（`...Z` /\n  /// `...+00:00` / 空格分隔）→ 范围比较返回静默错误的计数\"（见 `T08/risks.md` R10）。\n  /// 即使本表的 `occurredAt` 全由我们自己写、格式一致，把**可复算的数字**押在\n  /// \"字符串字典序恰好等于时间序\"上仍是脆的 —— 换一次写入路径就会破。\n  /// 期次是账单本来就有的概念，把它显式落列 ⇒ 对账退化为一次**纯等值比较**，\n  /// 与日期格式彻底解耦。\n  periodKey String\n\n  /// 来源资源的类型（`proposal` / `introduction` / `outcome` / `verification`）。\n  sourceType String\n\n  /// 来源资源 id（**软引用**，无 FK —— 账是历史，见文件头约束 3）。\n  sourceId String\n\n  /// 幂等键：同一来源事实只入账一次。唯一性作用域 = `(organizationId, dedupeKey)`。\n  /// 约定格式：`<unit-lower>:<sourceId>`（由 `usageDedupeKey()` 统一产出）。\n  dedupeKey String\n\n  createdAt DateTime @default(now())\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, dedupeKey])\n  @@index([organizationId, periodKey, unit])\n  @@index([organizationId, occurredAt])\n  @@index([sourceType, sourceId])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// V25.5 P0.1 · R-15 Durable Inbox（验签事件的持久化收件箱）\n//\n// 为什么单独建表而不是复用 BillingEvent / IdempotencyRecord：\n//   · BillingEvent 是**已结算的账**，装不下\"还没判决/待核验/人工复核\"的中间态；\n//   · IdempotencyRecord 是 HTTP 层同键回放，语义与本表（Provider 事件收件箱）不同；\n//   · 本表是\"事件先可靠落地、再判决、再写账\"的**缓冲 + 审计**层，\n//     ACK 与持久化绑定，杜绝\"回了 200 却没存下来\"的静默丢单。\n//\n// 设计约束（继承本文件）：纯新增表、方言无关、软引用优先、状态列由状态机写入\n// （本表是唯一一处\"状态落列\"是合理的地方 —— 它本来就是工作流状态，不是账本派生值）。\n/// 收件箱事件的处理状态。与 `src/lib/billing/inbox-state.ts` 的 InboxStatus 逐字对应。\nenum InboxEventStatus {\n  RECEIVED\n  APPLIED\n  SETTLED\n  NEEDS_PROVIDER_RECONCILIATION\n  RETRYABLE\n  REQUIRES_REVIEW\n  DEAD_LETTER\n}\n\nmodel BillingInboxEvent {\n  id String @id @default(cuid())\n\n  /// Provider delivery id（Standard Webhooks `webhook-id`）—— 首要幂等键，全局唯一。\n  deliveryId String @unique\n\n  /// Provider event id（可能与 deliveryId 不同）—— 次幂等键。\n  eventId String\n\n  organizationId String\n\n  /// 事件类型（payment.succeeded / payment.failed / ...）。\n  type String\n\n  paymentId      String?\n  subscriptionId String?\n  amountCents    Int?\n  currency       String?\n\n  /// 规范化 payload 的 sha256（**不存原文**，敏感信息最小化）。\n  payloadHash String\n\n  /// 工作流状态（由 inbox 状态机写入，非账本派生值）。\n  status InboxEventStatus @default(RECEIVED)\n\n  /// 已尝试处理次数（重试/核验耗尽 → DEAD_LETTER）。\n  attempts Int @default(0)\n\n  /// 最近一次判决说明/拒绝原因（only reason，不含敏感原文）。\n  lastNote String?\n\n  /// Provider 权威核验快照（JSON：`{status, verified, ...}`）；null = 未核验。\n  providerTruth Json?\n\n  /// 判决产生的结算命令（JSON 数组）；用于审计与 worker 崩溃后恢复重放。\n  resolutionCommands Json?\n\n  /// 幂等标记：账本命令是否已真实落库（防止\"判决了但没写账\"）。\n  appliedToLedger Boolean @default(false)\n\n  receivedAt DateTime\n  updatedAt  DateTime @updatedAt\n  createdAt  DateTime @default(now())\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, eventId])\n  @@index([organizationId, status, updatedAt])\n  @@index([status, updatedAt])\n  @@index([paymentId])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// P0-5 · Bot 可选模块 schema（2026-09-28 从核心 schema 移出）\n//\n// 本文件与 core.prisma 一起参与 prisma generate（同一 client、同一次生成），\n// 因此**业务代码零改动**。它的意义：\n//   · 多租户 / 开源核心改造只面对 core.prisma，6 张 Bot 表 + 4 个 Bot 枚举\n//     不再进入改造面（原估可减少约 14% 多租户改造量）\n//   · 开源发行构建可在打包时排除本文件（配合「默认关闭的可选模块」定位，\n//     见 docs/OPEN-CORE-POSITIONING.md §4；届时需同时移除 Bot 代码路径）\n//\n// 注意：User.isBot / botType / botConfig 是 User 表的列（核心侧），\n// 属数据列而非表，本阶段不迁移 —— 迁移它们需要破坏性 DB 变更。\n// ═══════════════════════════════════════════════════════════════\n\n// ═══════════════════════════════════════════════════════════════\n// BOT SYSTEM — Digital User Models\n// ═══════════════════════════════════════════════════════════════\n\nenum BotType {\n  SEED // 种子用户，冷启动用\n  SIMULATION // 行为模拟用户\n  TRAINING // 训练数据生成\n  ACTIVE // 活跃参与匹配\n}\n\nenum BotActivityLevel {\n  GHOST // 隐身，仅匹配不可见\n  LOW // 低活跃度 (10% 在线时间)\n  MEDIUM // 中活跃度 (30% 在线时间)\n  HIGH // 高活跃度 (60% 在线时间)\n  FULL // 全天候在线\n}\n\nenum Ethnicity {\n  CAUCASIAN\n  AFRICAN_AMERICAN\n  HISPANIC_LATINO\n  ASIAN\n  SOUTH_ASIAN\n  MIDDLE_EASTERN\n  MIXED\n  OTHER\n}\n\nenum OnlinePattern {\n  MORNING // 6AM-12PM\n  AFTERNOON // 12PM-6PM\n  EVENING // 6PM-12AM\n  NIGHT // 12AM-6AM\n  RANDOM\n  WORK_HOURS // 9AM-5PM\n  AFTER_WORK // 5PM-10PM\n}\n\n// Bot扩展资料 - 数字用户详细信息\nmodel BotProfile {\n  id        String @id @default(cuid())\n  // P0-5 拆分说明：与核心 Profile 的关联降级为普通列（DB 侧 FK 保留不变）。\n  // 跨文件 Prisma 关系要求 core.prisma 声明反向字段（P1012），会让核心 schema\n  // 重新引用 Bot 类型 —— 违背本拆分的目的。查询路径：先按 userId 查 Profile.id，\n  // 再按 profileId 查本表（见 src/lib/bot-automation.ts 的 findBotProfileByUserId）。\n  profileId String @unique\n\n  // 基础配置\n  botType       BotType          @default(SEED)\n  activityLevel BotActivityLevel @default(LOW)\n\n  // 人口统计扩展\n  ethnicity      Ethnicity?\n  occupation     String? // \"Software Engineer\", \"Teacher\", etc.\n  industry       String? // \"Tech\", \"Healthcare\", \"Finance\", etc.\n  educationLevel String? // \"High School\", \"Bachelor's\", \"Master's\", \"PhD\"\n  incomeRange    String? // \"$30k-50k\", \"$50k-100k\", etc.\n\n  // 兴趣与偏好 (JSON arrays - SQLite compatible)\n  interests   String @default(\"[]\") // JSON: [\"hiking\", \"cooking\", \"photography\"]\n  hobbies     String @default(\"[]\") // JSON: [\"gaming\", \"yoga\", \"reading\"]\n  musicGenres String @default(\"[]\") // JSON: [\"rock\", \"jazz\", \"electronic\"]\n  movieGenres String @default(\"[]\") // JSON: [\"thriller\", \"romance\", \"sci-fi\"]\n\n  // 行为模拟配置\n  onlinePattern   OnlinePattern @default(EVENING)\n  avgResponseTime Int           @default(30) // 平均响应时间（分钟）\n  maxDailyMatches Int           @default(3) // 每日最大匹配数\n\n  // 行为概率配置（JSON）\n  behaviorConfig String?\n\n  // 匹配偏好（扩展 Profile 的 preferred* 字段）(JSON arrays)\n  preferredEthnicities String @default(\"[]\") // JSON: Ethnicity[]\n  preferredOccupations String @default(\"[]\") // JSON: string[]\n  preferredEducation   String @default(\"[]\") // JSON: string[]\n\n  // 学习状态\n  totalInteractions  Int   @default(0)\n  successfulMatches  Int   @default(0)\n  avgEngagementScore Float @default(0) // 0-100\n\n  // 学习数据（JSON）\n  learningData String?\n\n  // 头像配置\n  avatarStyle  String? // \"professional\", \"casual\", \"artistic\"\n  avatarSource String? // \"generated\", \"stock\", \"ai_avatar\"\n\n  // 状态\n  isActive     Boolean   @default(true)\n  lastActiveAt DateTime?\n  sleepUntil   DateTime? // 暂停到指定时间\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([botType])\n  @@index([activityLevel])\n  @@index([isActive])\n}\n\n// Bot行为交互日志\nmodel BotInteractionLog {\n  id           String  @id @default(cuid())\n  botUserId    String\n  targetUserId String?\n  matchId      String?\n\n  // 交互类型\n  interactionType String // \"match_received\", \"match_reacted\", \"message_sent\", \"message_received\", \"profile_viewed\"\n\n  // 行为详情\n  action        String // \"accept\", \"pass\", \"respond\", \"initiate\"\n  responseDelay Int? // 响应延迟（秒）\n\n  // 结果\n  outcome         String? // \"success\", \"rejected\", \"no_response\", \"blocked\"\n  engagementScore Int? // 0-100 参与度评分\n\n  // 上下文\n  context String? // JSON: {matchScore, matchReason, etc.}\n\n  createdAt DateTime @default(now())\n\n  @@index([botUserId, createdAt])\n  @@index([interactionType])\n  @@index([outcome])\n}\n\n// Bot学习批次\nmodel BotLearningBatch {\n  id String @id @default(cuid())\n\n  // 批次信息\n  batchNumber Int\n  status      String @default(\"pending\") // pending, running, completed, failed\n\n  // 数据范围\n  startDate DateTime\n  endDate   DateTime\n\n  // 统计数据\n  totalInteractions Int   @default(0)\n  avgEngagement     Float @default(0)\n  successRate       Float @default(0)\n\n  // 更新的偏好配置\n  preferenceUpdates String? // JSON array of changes\n\n  // 执行日志\n  executionLog String?\n\n  createdAt   DateTime  @default(now())\n  completedAt DateTime?\n\n  @@index([status])\n  @@index([batchNumber])\n}\n\n// Bot学习记录 - 实时交互数据\nmodel BotLearningRecord {\n  id     String @id @default(cuid())\n  botId  String\n  userId String // 交互对象用户ID\n\n  // 交互类型\n  interactionType String // MATCH_REQUEST, MATCH_ACCEPT, CHAT_MESSAGE, etc.\n  outcome         String // POSITIVE, NEUTRAL, NEGATIVE\n\n  // 上下文数据\n  context String? // JSON string (SQLite compatible)\n\n  // 处理状态\n  processed Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([botId])\n  @@index([processed])\n  @@index([createdAt])\n  @@index([interactionType])\n}\n\n// Bot偏好向量 - 学习结果\nmodel BotPreference {\n  id    String @id @default(cuid())\n  botId String @unique\n\n  // 五维偏好 (0-1)\n  relationshipStructure Float @default(0.5)\n  communicationStyle    Float @default(0.5)\n  interests             Float @default(0.5)\n  values                Float @default(0.5)\n  lifestyle             Float @default(0.5)\n\n  // 元数据\n  confidence Float @default(0.1) // 置信度 (0-1)\n  sampleSize Int   @default(0) // 样本数量\n\n  createdAt   DateTime @default(now())\n  lastUpdated DateTime @updatedAt\n\n  @@index([botId])\n}\n\n// Bot头像管理\nmodel BotAvatar {\n  id           String  @id @default(cuid())\n  botId        String  @unique\n  originalUrl  String?\n  processedUrl String? // 处理后（压缩、优化）的URL\n\n  style     String // 原始风格\n  ethnicity String // 原始种族标签\n\n  status   String @default(\"pending\") // pending, active, failed, retired\n  useCount Int    @default(0) // 使用次数\n\n  generatedAt DateTime  @default(now())\n  lastUsedAt  DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ═══════════════════════════════════════════════════════════════\n// BRIDGE — T10 Community Bridge（跨社群授权与连接）\n//\n// 对齐：AC-19（跨社群**仅**共享明确 opt-in 的数据，**双边群主配置生效**）\n//\n// 设计约束（继承 agent.prisma / outcome.prisma 的同一套）：\n//   1. **纯新增** —— 不改动既有模型的任何列语义（零停机、零回归）。\n//   2. **方言无关** —— 不含任何 `@db.*` 原生类型标注。\n//   3. **软引用优先** —— `createdBy` / `revokedBy` / `BridgeMemberOptIn.userId`\n//      都不建 FK（用户注销后\"谁 opt-in 过什么\"仍须可查）；\n//      `initiatorOrgId` / `recipientOrgId` 同样**软引用** —— 协议是两个组织之间的\n//      **历史记录**，组织注销后仍应可查，且组织重建后**不得**继承旧协议。\n//      只有 `BridgeMemberOptIn.bridgeId` / `.organizationId` 建真 FK。\n//\n// ── 为什么是「协议 + 逐成员 opt-in」两张表，而不是一张 ──────────────\n//   AC-19 的两半是**不同主体**的授权：\n//     · 「双边群主配置生效」→ 协议层（谁有权开启共享）—— 组织级，需双方批准；\n//     · 「仅共享明确 opt-in 的数据」→ 成员层（谁被共享）—— 个人级，逐个加入。\n//   合成一张表就没法表达\"协议生效了、但张三没加入\"这种**正常**状态 ——\n//   而那恰恰是最常见的状态。故必须分开。\n//\n// ── JSON 列用 `String` 而非 `Json` ─────────────────────────────\n//   与 connection.prisma 的 `SocialIntent.disclosure` 同一取向：libSQL 下 `Json`\n//   落为 TEXT，Prisma 的 Json 解析对历史脏数据不够宽容（一个坏字符会打挂整行读取）。\n//   因此统一存文本、用 `src/lib/connection/json-codec` 的**容错**编解码，\n//   使\"一行脏数据\"只影响那一行，而不是整页。\n// ═══════════════════════════════════════════════════════════════\n\n/// 合作协议状态。**必须与 `src/lib/bridge/types.ts` 的 `BRIDGE_STATUSES` 逐字一致**\n/// （有漂移守卫：`tests/bridge/schema-drift.test.ts`）。\n///\n/// 🔴 刻意**没有** `EXPIRED`：过期是**派生值**（`expiresAt` 与当下时刻比较），\n///    落一个 `EXPIRED` 列就多出第二个事实来源、且需要 sweeper。\n///    查询一律带 `status = 'ACTIVE'`，过期行在 SQL 层即被排除（双保险）。\n/// 🔴 刻意**没有** `DRAFT`：发起方**创建即视为发起方已批准**，协议直接落 `PENDING`。\n///    留一个永不出现的 `DRAFT` 只会制造死状态。\nenum CommunityBridgeStatus {\n  PENDING\n  ACTIVE\n  REVOKED\n}\n\n/// 成员 opt-in 状态。**必须与 `BridgeMemberOptInStatus`（types.ts）逐字一致**。\n/// `WITHDRAWN` **保留行**（不删）—— 「谁曾加入过、何时退出」是审计问题。\nenum BridgeMemberOptInStatus {\n  ACTIVE\n  WITHDRAWN\n}\n\n/// 跨社群合作协议（组织 ↔ 组织，**双边**）。\nmodel CommunityBridge {\n  id String @id @default(cuid())\n\n  /// 发起方组织。**软引用**（无 FK）—— 见文件头约束 3。\n  initiatorOrgId String\n  /// 被邀方组织。**软引用**（无 FK）。\n  recipientOrgId String\n\n  /// 当前状态。只经 `src/lib/bridges/bridges.ts` 的 `transitionBridge()` 修改，\n  /// 且该函数在执行 UPDATE 前**必须**先过 `planBridgeTransition()` 的真相表断言。\n  status CommunityBridgeStatus\n\n  /// 发起方允许共享的字段键（JSON 数组文本）。\n  initiatorFieldKeys    String\n  /// 被邀方允许共享的字段键（JSON 数组文本）。\n  /// 🔴 共享字段 = 两者**交集**（只有双方都允许才生效）。\n  recipientFieldKeys    String\n  /// 可共享的任务类型（JSON 数组文本）。用途是收窄范围，不是枚举白名单的替代。\n  shareableMissionKinds String\n\n  /// 用途声明（purpose limitation）。**必填** —— 跨群共享必须有可陈述的目的。\n  purpose String\n\n  /// 发起方批准时刻。**创建时即落值**（创建 = 发起方同意）。\n  initiatorApprovedAt DateTime\n  /// 被邀方批准时刻。`null` ⇒ 协议仍停 `PENDING`（**不是**\"默认同意\"）。\n  recipientApprovedAt DateTime?\n\n  /// 有效期。`null` = 永久。\n  expiresAt DateTime?\n  revokedAt DateTime?\n  /// 撤销者（**软引用**）。\n  revokedBy String?\n  /// 创建者（**软引用**）。\n  createdBy String\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  memberOptIns BridgeMemberOptIn[]\n\n  /// 一对组织之间**同时只有一份**协议 —— 重复发起是幂等更新，不是新增行。\n  /// 库级保证：没有这条约束，\"同一对组织开两份协议\"会静默产生**双倍授权面**。\n  @@unique([initiatorOrgId, recipientOrgId])\n  /// 反查「我作为发起方/被邀方的协议」是列表页热路径。\n  @@index([initiatorOrgId, status])\n  @@index([recipientOrgId, status])\n  /// 「有没有即将过期的活跃协议」= 运营巡检查询。\n  @@index([status, expiresAt])\n}\n\n/// 成员的**逐个** opt-in。\nmodel BridgeMemberOptIn {\n  id String @id @default(cuid())\n\n  /// **真 FK**：协议删除必须级联清 opt-in —— 否则孤儿行会被投影当成\"有效授权\"。\n  bridgeId String\n\n  /// 成员所属组织。**真 FK**。\n  organizationId String\n\n  /// 成员。**软引用**（无 FK）—— 用户注销后\"谁曾加入\"仍须可查。\n  userId String\n\n  status BridgeMemberOptInStatus\n\n  /// 成员选择共享的字段键（JSON 数组文本）。\n  /// 必须 ⊆ 本组织在协议里配置的字段（`initiatorFieldKeys` 或 `recipientFieldKeys`）。\n  disclosedFieldKeys String\n\n  optedInAt   DateTime  @default(now())\n  withdrawnAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  bridge       CommunityBridge @relation(fields: [bridgeId], references: [id], onDelete: Cascade)\n  organization Organization    @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  /// 一人对一份协议只有一行 —— 重复 opt-in 是幂等更新（不是新增行）。\n  @@unique([bridgeId, userId])\n  @@index([organizationId, status])\n  @@index([userId, status])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// CONNECTION OS — 业务闭环实体（自 T02 起逐任务追加）\n//\n// 对齐契约：\n//   - contracts/schema.sql:15-20   (missions)\n//   - contracts/connection.openapi.yaml  /missions 与 /v1/missions/{missionId}\n//\n// 设计约束（继承 T01 的 tenancy.prisma，见 docs/implementation/T01/DIALECT-DIFF.md）：\n//   1. **方言无关**：本文件不出现任何 `@db.*` 原生类型标注。同一份定义可同时为\n//      libSQL（当前生产）与 PostgreSQL（M6 目标）生成；差异只体现在迁移 SQL。\n//   2. **复合语义字段走 `String` + 单点 codec**：libSQL 无 `jsonb`，契约里的\n//      `jsonb` 一律落为 JSON 文本，编解码**只允许**经 `src/lib/connection/json-codec.ts`。\n//      散落的 `JSON.parse` 会导致「有的存字符串、有的存对象」的静默腐化。\n//   3. **`organizationId` 一律由服务端从会话派生**（`resolveTenant()`），\n//      绝不接受客户端传入值作为授权依据。\n//   4. **加列优先 / 只增不改**：新任务只往本文件加模型；改动既有列语义需走 MIGRATION_PLAN。\n// ═══════════════════════════════════════════════════════════════\n\n/// Mission 生命周期。契约 missions.status 为自由 text（默认 'draft'），\n/// 这里收敛为枚举 —— 取值与 `src/lib/connection/missions.ts` 的状态机逐字一致。\nenum MissionStatus {\n  DRAFT // 草稿：不可分享，分享链接返回 404\n  ACTIVE // 已发布：分享页可访问，可被加入\n  PAUSED // 已暂停：分享页只读，拒绝新加入（保留历史）\n  CLOSED // 已关闭：分享页只读，终止\n}\n\n/// 成员加入 Mission 的状态。\n/// ⚠️ 与 T03 的 `SocialIntent` 分工：本模型只表达「谁加入了哪个任务」（粗粒度、必填），\n/// `SocialIntent` 表达「该成员的 need/offer/逐字段披露范围」（细粒度，T03 交付）。\n/// 二者是 1:1 互补关系，不是重复建模。\nenum MissionParticipationStatus {\n  INTERESTED // 已加入/表达参与意愿\n  WITHDRAWN // 本人撤销\n  REMOVED // 运营移出\n}\n\n/// 连接任务。对应契约 missions 表。\nmodel Mission {\n  id             String  @id @default(cuid())\n  /// 租户归属。**必填**（T01 起新表直接带上，不再走加列批次）。\n  organizationId String\n  /// 任务发起人。契约 persons 同义于本仓 `User`。\n  ownerId        String\n  /// V21 · Mission ↔ AgentRun **真实关联锚点**（纯新增、可选）。\n  /// 仅接受本组织内真实存在且 `skill=INTENT_EXTRACTION` 的 run —— 校验在\n  /// `createMission()` 里带 `{ id, organizationId, skill }` 谓词回查，绝不采信\n  /// 客户端传来的其它身份字段。软引用（不建 FK）：运行记录是证据，不应因\n  /// 关联任务被清理而反向受约束；租户隔离由 organizationId 谓词保证。\n  /// null = 该任务不是由意图抽取运行派生（旧数据全部为 null）。\n  sourceRunId    String?\n\n  title           String\n  goal            String\n  offer           String\n  /// 约束（JSON 文本，字符串数组）。**必须**经 json-codec 读写。\n  constraints     String?\n  /// 成功标准：验收「连接是否达成」的判据（PRD 要求可判定，非口号）。\n  successCriteria String\n\n  status MissionStatus @default(DRAFT)\n\n  /// 分享令牌：`/m/<shareToken>` 的唯一寻址方式。\n  /// 高熵、不可枚举、URL-safe；**即能力凭证**，故不可预测、不可自增。\n  shareToken    String  @unique\n  /// 是否允许**未注册**访客预览（最小披露）。关闭后分享页一律要求登录。\n  publicPreview Boolean @default(true)\n\n  /// 限额。null = 不限。\n  maxParticipants Int?\n\n  expiresAt   DateTime? // 截止（过期后分享页只读、拒绝新加入）\n  publishedAt DateTime? // 首次 publish 时间\n  closedAt    DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  organization   Organization           @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  owner          User                   @relation(\"UserMissions\", fields: [ownerId], references: [id], onDelete: Cascade)\n  participations MissionParticipation[]\n  socialIntents  SocialIntent[]\n  proposals      ConnectionProposal[]\n\n  @@index([organizationId, status])\n  @@index([organizationId, createdAt])\n  @@index([expiresAt])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// T03 · SocialIntent —— 成员意图与**逐字段披露**\n//\n// 与 MissionParticipation 的分工（不是重复建模）：\n//   - MissionParticipation：粗粒度「谁加入了哪个任务」（T02，必填、可计数）\n//   - SocialIntent：       细粒度「该成员的 need/offer/约束/有效期 + 逐字段可见范围」（T03）\n//   二者 1:1 互补；意图必须挂在一条已加入的参与关系之下（父锚点 `missionId + userId`）。\n//\n// 安全取向（AC-03 是 BLOCKER）：**默认拒绝**。`disclosure` 里没写的字段一律按\n// field-catalog 的 defaultAudience 处理，而目录中每个字段的默认值都是 `SELF`\n// （即不披露）。「用户没选」**绝不**等价于「用户同意」。\n// ═══════════════════════════════════════════════════════════════\n\n/// 意图生命周期。**只有本人能改**；`WITHDRAWN` 是终态（重新参与须显式 reactivate）。\n///\n/// 「已过期」**刻意不落库**：它由 `expiresAt` 与当前时间**派生**\n/// （见 `intents.ts` 的 `deriveIntentStatus()`）。若把它做成存储状态，\n/// 就必须依赖定时任务翻状态 —— 定时任务一旦停摆，「过期」会静默失效，\n/// 而已过期意图仍在被披露。派生状态没有这个失败模式。\nenum IntentStatus {\n  ACTIVE // 生效中：可被披露、可进入匹配\n  WITHDRAWN // 本人撤销：不再披露，且不可编辑（须 reactivate 显式复活）\n}\n\n/// 逐字段披露的受众档位。**档位是包含式的**（档位越高 = 允许看到的人越多）：\n///   SELF          → 仅本人（= 不披露）\n///   ORGANIZER     → 本人 + 组织者\n///   COUNTERPARTY  → 本人 + 组织者 + **已双向同意**的对手方（T05 起）\n///   CANDIDATE     → 本人 + 组织者 + 同任务的互补伙伴（T04 起；最宽）\n/// 因此\"某受众能否看到\" = `rank(granted) >= rank(viewer)`。\n///\n/// ⚠️ 为什么 `CANDIDATE` 排在 `COUNTERPARTY` **之后**（而不是\"候选比对手方窄\"）：\n///   记 `C` = 已同意的对手方集合，`P` = 同任务的互补伙伴集合。**`C ⊆ P`** ——\n///   任何已同意的对手方，在同意之前本来就是一名候选伙伴。于是\n///   `{组织者}+C ⊆ {组织者}+P`，即\"给已同意者看\" ⊂ \"给伙伴看\"。\n///   `CANDIDATE` 因此是**更宽**的一档，必须追加在末尾。\n///   若误以为\"候选更窄\"而把它插在 `COUNTERPARTY` 之前，就会出现\n///   `rank(COUNTERPARTY) >= rank(CANDIDATE)` → **尚未同意的人看到了用户\n///   只授权给已同意对手方的字段** —— 一次静默的越权披露。\n///\n/// ⚠️ 新增档位时**不得改变已存在档位的相对次序**：库里存的是档位**名字**，\n///   理解名字的是本次序；次序一变，历史数据的可见性会静默漂移，\n///   且没有任何迁移能\"顺便修好\"它。（`CANDIDATE` 追加在末尾即满足此约束。）\n///\n/// 用 `///` 是为了让这条规则进入生成的 Client 类型提示，避免调用方凭直觉猜方向。\nenum DisclosureAudience {\n  SELF // 仅本人可见（= 不披露）\n  ORGANIZER // 任务组织者 / 运营\n  COUNTERPARTY // 双向同意后的对手方（T05 起生效）\n  CANDIDATE // 同任务的互补伙伴（尚未同意；T04 起生效，最宽）\n}\n\n/// 成员意图。对应契约 social_intents 表的语义（契约挂在 organization 上，\n/// 本仓显式挂到 Mission —— 意图脱离具体任务没有业务含义，且 mission 级才能做名额/披露判定）。\nmodel SocialIntent {\n  id             String @id @default(cuid())\n  organizationId String\n  /// 父锚点：T02 的 Mission。任务删除时意图级联删除。\n  missionId      String\n  /// 提交者。**必须**是该 Mission 所属租户的 ACTIVE 成员（服务端回查 memberships）。\n  userId         String\n\n  /// 我需要什么（Mission 的 goal 是\"发起方要什么\"，这里是\"协作者要什么\"）。\n  need        String\n  /// 我能提供什么。\n  offer       String\n  /// 附加约束（JSON 文本，字符串数组）。**必须**经 json-codec 读写。\n  constraints String?\n\n  /// 逐字段披露表（JSON 文本）：`{ \"<fieldKey>\": \"SELF\"|\"ORGANIZER\"|\"CANDIDATE\"|\"COUNTERPARTY\" }`。\n  ///\n  /// 语义：**缺失的键 = 未授权**（落到目录默认值 SELF），不在这里补默认值 ——\n  /// 「写库时补默认」会把\"用户没选\"悄悄固化成\"系统认为他同意了\"。\n  disclosure String?\n\n  status IntentStatus @default(ACTIVE)\n\n  /// 有效期。null = 不过期。过期后**仍可编辑续期**，但不再被披露（派生为 EXPIRED）。\n  expiresAt   DateTime?\n  withdrawnAt DateTime?\n\n  /// ── 导入许可留痕（AC-12「用户主动授权」的落点）──\n  /// 用户显式同意「从账户档案导入字段」的**时间戳**。null = 从未同意，\n  /// 此时任何 `importFromProfile` 请求都必须被拒（400），不得默认放行。\n  importConsentAt DateTime?\n  /// 实际从档案导入的字段名（JSON 文本数组）。与 `disclosure` **分开存储**：\n  /// 一个记\"数据从哪来\"、一个记\"给谁看\"。混在一起会导致\"撤回导入\"误删披露设置。\n  importedFields  String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  mission      Mission      @relation(fields: [missionId], references: [id], onDelete: Cascade)\n  user         User         @relation(\"UserSocialIntents\", fields: [userId], references: [id], onDelete: Cascade)\n\n  /// 同一任务同一成员只有一条意图 —— 幂等提交/编辑的落点。\n  @@unique([missionId, userId])\n  @@index([organizationId, status])\n  @@index([organizationId, missionId])\n  @@index([userId, status])\n  @@index([expiresAt])\n}\n\n/// 成员 × Mission 的加入关系。契约中没有独立表（契约把 memberships 与\n/// social_intents 直接挂 organization），这里显式建模是为了：\n///   1. 让「加入」可计数、可撤销、可审计（AC-11 的加入动作需要落库）；\n///   2. 给 T03 的 `SocialIntent` 一个稳定的父锚点（`missionId` + `userId`）。\nmodel MissionParticipation {\n  id             String                     @id @default(cuid())\n  organizationId String\n  missionId      String\n  userId         String\n  status         MissionParticipationStatus @default(INTERESTED)\n  /// 加入时的可选留言（最小披露：不进入公开投影）。\n  note           String?\n  createdAt      DateTime                   @default(now())\n  updatedAt      DateTime                   @updatedAt\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  mission      Mission      @relation(fields: [missionId], references: [id], onDelete: Cascade)\n  user         User         @relation(\"UserMissionParticipations\", fields: [userId], references: [id], onDelete: Cascade)\n\n  /// 同一任务同一成员只能有一条加入记录（幂等 join 的落点）。\n  @@unique([missionId, userId])\n  @@index([organizationId, status])\n  @@index([userId, status])\n}\n\n/// 幂等记录。契约对 `POST /missions` 强制要求 `Idempotency-Key` 请求头\n/// （connection.openapi.yaml:12-19）。同样的键重复提交必须返回**首次结果**，\n/// 不得创建第二条 Mission —— 这是 AC-07（幂等）在本任务的最小落点。\n///\n/// 键空间是 `(organizationId, scope, key)`：同一把 key 在不同租户/不同业务动作下\n/// 互不干扰，避免跨租户串号。\nmodel IdempotencyRecord {\n  id             String   @id @default(cuid())\n  organizationId String\n  /// 业务动作，如 `mission.create` / `mission.join`。\n  scope          String\n  /// 客户端提交的 Idempotency-Key 原文。\n  key            String\n  /// 请求体指纹（sha256）。同一 key 配不同请求体 → 409（防止「键复用了但意图变了」）。\n  requestHash    String\n  resourceType   String\n  resourceId     String?\n  /// V21/R3：发起人身份（服务端会话 userId），纯新增可选列；旧数据一律为 null。\n  /// 不改 @@unique([organizationId, scope, key])（会破坏迁移与旧数据）：键空间按用户\n  /// 分区由 `scope` 后缀实现，本列只作「命中后校验」的纵深防御，不参与唯一约束。\n  actorId        String?\n  createdAt      DateTime @default(now())\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, scope, key])\n  @@index([organizationId, createdAt])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// T05 · 双边同意（Consent & Trust）—— AC-04 / AC-05 / AC-06\n//\n// 契约对应：\n//   - contracts/schema.sql:693-704   (connection_proposals / proposal_decisions)\n//   - contracts/connection.openapi.yaml   POST /connections/proposals、\n//     POST /connections/{connectionId}/consent、POST /connections/{connectionId}/revoke\n//\n// ⚠️ **为什么不复用 core.prisma 的 `ConsentRequest` / `ConsentGrant`**\n//   （卡片写\"可复用\"，此处是逐条核对后的判定，不是偷懒新造表）：\n//   那两个模型是 **IM 媒体访问权限** —— `consentType: MEDIA`、\n//   `requestedLevel/grantedLevel: L0_TEXT | …`、外键 `conversationId` 挂在**会话**上，\n//   语义是\"允许对方看我的摄像头 / 麦克风 / 加密消息\"。\n//   本任务要表达的是\"**组织者牵线，与另一个人建立连接**\"：没有会话、没有媒体档位、\n//   参与者是「提案双方」而非「会话双方」。\n//   硬塞进 `ConsentRequest` 需要把 `conversationId` 改成可空、并给 `consentType`\n//   加一个与 `MEDIA` 并列的取值 —— 结果是**两个语义域共用一张表**：\n//   媒体权限的查询会捞到连接提案，反之亦然（且没有任何编译期信号）。\n//   契约本身把二者分表（`consent_grants` vs `connection_proposals`），本仓遵循契约。\n//   可以复用的是**模式**而非表：拒绝即关闭、撤销清空待发、执行前再校验。\n// ═══════════════════════════════════════════════════════════════\n\n/// 连接提案的生命周期。\n///\n/// ⚠️ 与 T03 `IntentStatus` 的根本差别：这是**双人**状态机。\n///   单人同意**不改变**\"待决\"这一事实 —— `CONSENT_PENDING` 会跨越第一次 accept。\n///   因此\"能否介绍\"的判据**不是** \"有人同意了\"，而是 `MUTUALLY_ACCEPTED`\n///   （AC-04：单方接受不得发送正式介绍）。\nenum ConnectionProposalStatus {\n  CONSENT_PENDING // 待决：至少一方尚未表态（刚创建时即此态）\n  MUTUALLY_ACCEPTED // 双方均已接受 —— **\"可介绍\"的唯一状态**\n  REJECTED // 任一方拒绝：终态，之后任何表态一律 409\n  REVOKED // 任一方撤销：终态；也可从 MUTUALLY_ACCEPTED 撤销（AC-05）\n}\n\n/// 个体表态类型。对应契约 `proposal_decisions.decision CHECK IN ('accept','reject','revoke')`。\nenum ProposalDecisionKind {\n  ACCEPT\n  REJECT\n  REVOKE\n}\n\n/// 连接提案。对应契约 `connection_proposals` 表。\nmodel ConnectionProposal {\n  id             String @id @default(cuid())\n  organizationId String\n  /// 提案依附的 Mission —— 互补关系是在某条任务下被发现并牵线的。\n  missionId      String\n\n  /// 发起方。**必须**是同租户 ACTIVE 成员且具备 `proposal.create`（T01 定为 OPERATOR+）。\n  proposerId  String\n  /// 被介绍方。**必须**是同租户 ACTIVE 成员，且与发起方不是同一人（契约 CHECK 的等价约束）。\n  candidateId String\n\n  status ConnectionProposalStatus @default(CONSENT_PENDING)\n\n  /// 发起理由。**会展示给被介绍方** —— 这是对方决定\"要不要同意\"的唯一依据，\n  /// 故必填（契约 `rationale text NOT NULL`）。不得写入内部判断或他人隐私。\n  rationale String\n\n  /// 提案有效期。null = 不过期。\n  /// ⚠️ AC-06：**执行（介绍）时必须再校验一次本字段**，不能只在创建时校验 ——\n  /// 提案完全可能在\"双方都同意\"与\"真正介绍\"之间失效。\n  expiresAt DateTime?\n\n  /// 介绍落地时间。null = 尚未介绍。写入即代表\"连接已建立\"，T06 据此驱动后续工作流。\n  introducedAt DateTime?\n  /// 关闭时间（进入 REJECTED / REVOKED 时写入），用于审计与\"提案存活时长\"统计。\n  closedAt     DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  organization         Organization          @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  mission              Mission               @relation(fields: [missionId], references: [id], onDelete: Cascade)\n  proposer             User                  @relation(\"ProposalProposer\", fields: [proposerId], references: [id], onDelete: Cascade)\n  candidate            User                  @relation(\"ProposalCandidate\", fields: [candidateId], references: [id], onDelete: Cascade)\n  decisions            ProposalDecision[]\n  /// T06：一提案至多一条介绍工作流（1:1）。提案删除时工作流级联删除。\n  introductionWorkflow IntroductionWorkflow?\n\n  /// 同一对（发起方 → 被介绍方）在同一任务下**只能有一条提案**。\n  /// 这同时是\"重复发起\"的最后一道兜底：即便客户端换了 `Idempotency-Key`，\n  /// 也不会为同一对搭档堆出多条并行同意流程 —— 那会把\"双方同意\"退化成\n  /// \"同意其中一条\"，而另外几条仍在待决（用户看到的界面会自相矛盾）。\n  @@unique([missionId, proposerId, candidateId])\n  @@index([organizationId, status])\n  @@index([organizationId, missionId])\n  @@index([proposerId, status])\n  @@index([candidateId, status])\n  @@index([expiresAt])\n}\n\n/// 个体表态记录。契约 `PRIMARY KEY(proposal_id, person_id)` —— 每人每提案**至多一行**。\n///\n/// 语义：这是「**当前**表态」，不是「表态流水」。同一人先 accept 后 revoke 时，\n/// 本行被**覆盖**（AC-05 的撤销即由此实现），而不是追加一行 ——\n/// 保留流水会把\"谁在什么时候改过主意\"变成永久记录，那不是本任务要收集的数据。\n/// 需要不可抵赖的追加式记录请走 `TenantAuditEvent`（写入失败不影响业务）。\nmodel ProposalDecision {\n  id             String @id @default(cuid())\n  organizationId String\n  proposalId     String\n  /// 表态人。服务层**必须**校验其 ∈ {proposerId, candidateId}（非参与者 → 403，不得 404 —— \n  /// 提案对非参与者而言是\"存在但不关你的事\"，与跨租户的\"不存在\"是两种不同的答复）。\n  personId       String\n\n  decision  ProposalDecisionKind\n  /// 可选说明。**不返回给对侧** —— 否则\"拒绝理由\"就成了一次计划外的信息披露。\n  note      String?\n  decidedAt DateTime             @default(now())\n\n  organization Organization       @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  proposal     ConnectionProposal @relation(fields: [proposalId], references: [id], onDelete: Cascade)\n  person       User               @relation(\"UserProposalDecisions\", fields: [personId], references: [id], onDelete: Cascade)\n\n  @@unique([proposalId, personId])\n  @@index([organizationId])\n  @@index([personId, decidedAt])\n  @@index([decision])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// T06 · Workflow Execution — 可靠投递与跟进状态机\n//\n// 对齐验收：AC-07（幂等）/ AC-09（消息合规）/ AC-14（介绍工作流）/ AC-17（工作流恢复）\n//\n// 引擎选型（BACKLOG §6-⑤ 的拍板结果）：**DB outbox**，不引入 Temporal。理由：\n//   1. 现网部署是 Netlify **免费计划** —— 无常驻进程，跑不了 Temporal worker；\n//   2. 现网 DB 是 libSQL，而 Temporal 需要 PG/MySQL —— 引入它等于先做尚未拍板的 M6；\n//   3. 本仓已有 `cron-runner` 调度器（netlify/functions）+ 内部 cron 端点（CRON_SECRET 守卫）\n//      + T02 幂等层 + T05 的 CAS 范式 —— outbox 是**零新增基础设施**的路线；\n//   4. PRD 明确「早期一个可靠的数据库任务队列就足够」，架构文档把 Temporal 定为\n//      「工作流复杂度确有必要时引入」。**替换点**已隔离在 `src/lib/workflow/runtime.ts`\n//      的驱动接口上，届时只需换驱动器，不改业务侧调用点。\n//\n// ⚠️ **软引用，不是外键**（刻意）：`WorkflowJob.proposalId` / `missionId` 与\n//   `NotificationDelivery.recipientId` 都不建 FK relation，只存 id 字符串。\n//   理由：outbox 与投递记录是**已发生事实的留痕**，其存在不能取决于被引用行是否还在。\n//   若建 FK 级联，「删掉提案」会连带抹掉「我们曾尝试投递、失败了几次、最终怎么收场」——\n//   那正是 AC-17（故障注入后可观测、可接管）最需要的那份证据。\n//   这与 `TenantAuditEvent.resourceId` 的取向一致（同样是软引用）。\n// ═══════════════════════════════════════════════════════════════\n\n/// 工作流任务类型。每个类型对应一处「业务动作之后的副作用」。\nenum WorkflowJobKind {\n  PROPOSAL_CREATED // 提案创建 → 通知被介绍方（消解 T05 R4「没人被通知」）\n  CONSENT_ACCEPTED // 一方表态 → 通知另一方（含\"已同意，等待对方\"的阶段性提示）\n  INTRODUCE_CONNECTION // 双方同意 → 执行介绍（**投递钩子**：原样调用 introduceConnection()）\n  COORDINATION_FOLLOWUP // 介绍落地 → 跟进提示（AC-14 的\"跟进\"段）\n}\n\n/// 任务状态机。\n///\n/// ⚠️ `DEAD` 与 `TAKEN_OVER` **不是同一件事**，不要合并：\n///   - `DEAD`：自动重试已耗尽 → 需要人判断\"是否还该送\"。系统已放弃。\n///   - `TAKEN_OVER`：人**主动**接管（可能发生在 DEAD 之后，也可能在重试中途）。\n///     接管后**自动重试必须停止** —— 否则人的处置会被自动重试覆盖。\nenum WorkflowJobStatus {\n  PENDING // 待执行（`nextAttemptAt` 到点前不可领）\n  RUNNING // 已被领取（持租约；租约过期 = 上一个执行者崩了，可被重新领取）\n  SUCCEEDED // 执行成功（终态）\n  FAILED // 不可重试的终态失败（如校验不通过：重试一万次也一样）\n  DEAD // 死信：可重试但重试次数耗尽（终态，等待人工）\n  TAKEN_OVER // 人工接管（终态；不再自动重试）\n  CANCELLED // 被上游撤销取消（AC-05「撤销取消待发任务」的落点）\n}\n\n/// 投递渠道。**仅这两条** —— 主指令要求\"仅用官方授权渠道，禁止绕过平台 API\"。\nenum NotificationChannel {\n  IN_APP // 站内通知（写 Notification 表，真实落库）\n  EMAIL // 邮件（统一出口；无真实凭据时进沙箱捕获，**不伪造已发送**）\n}\n\n/// 投递结果。\n///\n/// ⚠️ `CAPTURED` 与 `SENT` **必须分开**：前者是\"沙箱捕获了投递意图与内容\"，\n///   后者是\"真实外部服务已受理\"。把沙箱写成 SENT 就是虚报外部服务已接通\n///   （主指令：「没有真实凭据的流程只能标记 MOCKED / BLOCKED，不能标记 PASSED」）。\nenum NotificationDeliveryStatus {\n  PENDING\n  SENT // 真实渠道已受理（provider 回执 id 落库）\n  CAPTURED // 沙箱捕获（无凭据）：记录内容与边界，供断言，不冒充已送达\n  FAILED\n}\n\n/// 介绍工作流的阶段（AC-14 的端到端链路）。\n///\n/// 与 `ConnectionProposalStatus` 的关系：后者是**授权**状态机（谁同意了），\n/// 本枚举是**流程**状态机（事情走到哪一步了）。二者不合并 —— 一次授权可能\n/// 对应多次流程推进（如介绍后协调、完成、记成果），而授权在介绍落地后就冻结了。\nenum WorkflowStage {\n  PROPOSED // 提案已创建，等待表态\n  CONSENT_PENDING // 至少一方已表态但未双方同意\n  INTRODUCED // 介绍已落地（introducedAt 已写）\n  COORDINATING // 双方正在协调（跟进中）\n  ACTION_COMPLETED // 连接行动已完成\n  OUTCOME_RECORDED // 成果已记录（T08 接手后的终态）\n}\n\n/// Outbox / 任务队列。**一张表同时承载待执行、重试、死信、接管** ——\n/// 拆成多表会让\"一个任务的一生\"跨三张表，而 AC-17 要求能一眼看清它的处境。\nmodel WorkflowJob {\n  id             String @id @default(cuid())\n  organizationId String\n\n  /// **幂等键**（AC-07 的落点）：同一业务动作重复入队只会有一行。\n  /// 例：`introduce:<proposalId>`、`proposal-created:<proposalId>`。\n  /// 唯一约束 `(organizationId, dedupeKey)` 让并发入队退化为\"第二次撞唯一键\"，\n  /// 而不是\"两条任务各投递一次\"。\n  dedupeKey String\n\n  kind   WorkflowJobKind\n  status WorkflowJobStatus @default(PENDING)\n\n  /// 软引用（见文件头说明）：不建 FK，删提案不抹掉投递痕迹。\n  proposalId String?\n  missionId  String?\n\n  /// 载荷（JSON 文本，经 json-codec 读写）。\n  /// ⚠️ **禁止**放 rationale 全文与对侧档案字段 —— 任务是内部调度凭据，\n  /// 不是信息披露通道。披露只能经 `discloseSubject()`（T03 的唯一出口）。\n  payload String?\n\n  // ── 重试与退避 ──\n  attempts      Int      @default(0)\n  maxAttempts   Int      @default(5)\n  /// 下次可被领取的时间。退避 = 指数 + 抖动（见 `src/lib/workflow/backoff.ts`）。\n  nextAttemptAt DateTime @default(now())\n\n  // ── 租约（AC-17 崩溃恢复的落点）──\n  /// 领取者标识（worker 实例名）。租约到期后他人可重新领取。\n  lockedBy    String?\n  lockedUntil DateTime?\n\n  /// 最后一次失败原因（截断存储，仅供排障。**禁止**写入正文内容）。\n  lastError String?\n\n  /// 进入死信的时间。\n  deadLetteredAt DateTime?\n  /// 人工接管者与时间。接管后自动重试停止。\n  takenOverBy    String?\n  takenOverAt    DateTime?\n  /// 被上游取消的时间（AC-05：撤销要能取消待发任务）。\n  cancelledAt    DateTime?\n\n  completedAt DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  /// **AC-07 的硬保证**：同一租户内同一业务动作至多一行任务。\n  @@unique([organizationId, dedupeKey])\n  /// 领取与扫描的主索引：`(status, nextAttemptAt)` 先过滤再排序。\n  @@index([status, nextAttemptAt])\n  /// 租户内的运营视图（\"本社群卡住的任务\"）。\n  @@index([organizationId, status, nextAttemptAt])\n  @@index([organizationId, proposalId])\n}\n\n/// 消息投递记录（**审计面**：到底给谁、发了什么、走的哪个渠道、结果如何）。\n///\n/// 与 `Notification`（core.prisma，站内信的**收件箱**）分工：\n///   - `Notification`   → 用户能看到的那条消息（可能被已读/删除）。\n///   - `NotificationDelivery` → 我们**投递过**这件事的记录（不可被用户删除，是 AC-09 的证据）。\n/// 二者不是重复建模：一条投递可能因为去重而**不**产生新 `Notification`，\n/// 也可能在 `Notification` 被删后仍需保留投递证据。\nmodel NotificationDelivery {\n  id             String @id @default(cuid())\n  organizationId String\n\n  /// 幂等键：`<kind>:<proposalId>:<recipientId>` —— 同一业务动作对同一人只投递一次。\n  dedupeKey String\n\n  channel NotificationChannel\n  status  NotificationDeliveryStatus @default(PENDING)\n\n  /// 软引用（见文件头说明）：收件人注销后投递记录仍需留存。\n  recipientId String\n\n  /// 模板标识（如 `proposal.pending`）。决定文案骨架，与人无关，故可安全落库。\n  template  String\n  subject   String?\n  /// 渲染后的正文。**系统生成**，只含最小披露信息。\n  body      String\n  actionUrl String?\n\n  /// ── 沙箱捕获（AC-09 的证据面）──\n  /// 无真实凭据时不外发，但把\"要发什么\"记下来：`CAPTURED` + 本字段非空。\n  capturedAt        DateTime?\n  /// 实际渠道：`in-app` / `resend` / `smtp` / `sandbox`。\n  provider          String?\n  providerMessageId String?\n  failureReason     String?\n\n  sentAt    DateTime?\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, dedupeKey])\n  @@index([organizationId, recipientId, createdAt])\n  @@index([organizationId, status])\n}\n\n/// 介绍工作流实例（**一提案一条**）。记录 AC-14 那条链走到哪一步、每一步何时发生。\nmodel IntroductionWorkflow {\n  id             String @id @default(cuid())\n  organizationId String\n  /// 1:1 绑定提案。强 FK：提案没了，这条流程也就没有意义了。\n  proposalId     String @unique\n  /// 软引用：missionId 只用于租户内筛选。\n  missionId      String\n\n  stage          WorkflowStage @default(PROPOSED)\n  /// 进入当前阶段的时间（**超时判定的基准**；AC-17 的\"超时\"落点）。\n  stageEnteredAt DateTime      @default(now())\n\n  /// 阶段时间线（JSON 文本数组）：`[{stage, at, by, reason}]`，追加式。\n  /// 与 `ProposalDecision` 相反，这里**刻意留流水** —— 流程推进需要可复盘。\n  timeline String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  organization Organization       @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  proposal     ConnectionProposal @relation(fields: [proposalId], references: [id], onDelete: Cascade)\n\n  @@index([organizationId, stage])\n  @@index([organizationId, missionId])\n}\n\n// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../../src/generated\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n}\n\n// ═══════════════════════════════════════════════════════════════\n// AUTH — NextAuth v5 compatible models\n// ═══════════════════════════════════════════════════════════════\n\nmodel User {\n  id            String    @id @default(cuid())\n  name          String?\n  email         String    @unique\n  emailVerified DateTime?\n  image         String?\n\n  // Auth\n  password     String?\n  role         UserRole  @default(USER)\n  tokenVersion Int       @default(0) // bumped on password change/reset to invalidate all previously-issued JWT sessions\n  accounts     Account[]\n  sessions     Session[]\n\n  // Bot/Digital User Flags\n  isBot     Boolean @default(false) // 标记是否为数字用户\n  botType   String? // \"simulation\" | \"training\" | \"seed\"\n  botConfig String? // 数字用户行为配置（JSON字符串存储）\n\n  // Email Verification\n  verificationTokens VerificationToken[] @relation(\"UserVerificationTokens\")\n\n  // Profile\n  profile Profile?\n\n  // Matching\n  sentMatches     Match[]         @relation(\"SentMatches\")\n  receivedMatches Match[]         @relation(\"ReceivedMatches\")\n  matchReactions  MatchReaction[]\n\n  // Chat\n  // P1-6 阶段 5：原 `chatRooms ChatRoomMember[]` / `messages Message[]` 关系\n  // 随 Legacy 三表删除而移除。\n\n  // IM Module\n  conversationsA      Conversation[]            @relation(\"ConversationUserA\")\n  conversationsB      Conversation[]            @relation(\"ConversationUserB\")\n  imMessages          IMMessage[]               @relation(\"IMMessageSender\")\n  messageReceipts     MessageReceipt[]\n  messageReactions    MessageReaction[]\n  imParticipants      ConversationParticipant[]\n  presence            UserPresence?\n  powerBoardRule      PowerBoardRule?\n  consentRequestsMade ConsentRequest[]          @relation(\"ConsentRequester\")\n  consentRequestsRecv ConsentRequest[]          @relation(\"ConsentTarget\")\n  consentGrantsMade   ConsentGrant[]            @relation(\"ConsentGranter\")\n  consentGrantsRecv   ConsentGrant[]            @relation(\"ConsentGrantee\")\n  auditLogs           AuditLog[]\n\n  // Payments\n  subscriptions Subscription[]\n  payments      Payment[]\n\n  // Notifications\n  notifications Notification[]\n\n  // Admin\n  adminAudits AdminAudit[] @relation(\"AdminAuditActor\")\n\n  // RBAC — 管理角色关联\n  adminRoles AdminUserRole[]\n\n  // T01 多租户 — 成员关系（模型定义见 prisma/schema/tenancy.prisma）\n  memberships Membership[] @relation(\"UserMemberships\")\n\n  // T02 Connection OS — Mission 发起 / 参与（模型定义见 prisma/schema/connection.prisma）\n  missions              Mission[]              @relation(\"UserMissions\")\n  missionParticipations MissionParticipation[] @relation(\"UserMissionParticipations\")\n\n  // T03 Connection OS — 成员意图与逐字段披露（模型定义见 prisma/schema/connection.prisma）\n  socialIntents SocialIntent[] @relation(\"UserSocialIntents\")\n\n  // T05 Connection OS — 连接提案与个体表态（模型定义见 prisma/schema/connection.prisma）\n  //\n  // 三个关系**必须分开命名**：同一个人既可能是「发起方」也可能是「被介绍方」，\n  // 若共用一个关系名，Prisma 无法确定提案的两个外键各自指向哪一侧 ——\n  // 生成出来的 client 会把 proposer/candidate 混淆（编译期不报错，写入时错位）。\n  proposalsMade     ConnectionProposal[] @relation(\"ProposalProposer\")\n  proposalsReceived ConnectionProposal[] @relation(\"ProposalCandidate\")\n  proposalDecisions ProposalDecision[]   @relation(\"UserProposalDecisions\")\n\n  // Analytics\n  analyticsEvents AnalyticsEvent[]\n\n  // Safety & Moderation\n  reportsMade     UserReport[] @relation(\"ReportsMade\")\n  reportsReceived UserReport[] @relation(\"ReportsReceived\")\n\n  // Block List\n  blocksGiven    Block[] @relation(\"BlockerRelations\")\n  blocksReceived Block[] @relation(\"BlockedRelations\")\n\n  // Sincerity\n  sincerityWallet SincerityWallet?\n\n  // Credit Card Verification (age + identity proof, no charge)\n  cardVerified   Boolean   @default(false)\n  cardVerifiedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Soft delete (v3.0)\n  deletedAt DateTime?\n\n  @@index([email])\n  @@index([role])\n  @@index([createdAt])\n  @@index([deletedAt])\n  @@index([isBot]) // P1: AutoMatch bot 查找\n}\n\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String?\n  access_token      String?\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String?\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel VerificationToken {\n  id         String    @id @default(cuid())\n  identifier String // email address\n  token      String    @unique // the 6-digit code\n  expires    DateTime\n  userId     String? // optional link to user\n  user       User?     @relation(\"UserVerificationTokens\", fields: [userId], references: [id], onDelete: Cascade)\n  used       Boolean   @default(false)\n  useCount   Int       @default(0) // Track usage count for replay attack prevention\n  maxUses    Int       @default(1) // Maximum allowed uses (1 for one-time tokens)\n  lastUsedAt DateTime? // Track when token was last used\n  createdAt  DateTime  @default(now())\n\n  @@unique([identifier, token])\n  @@index([identifier])\n  @@index([userId])\n  @@index([expires])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// USER PROFILE — Relationship structure blueprint\n// ═══════════════════════════════════════════════════════════════\n\nmodel Profile {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Basic Info\n  displayName    String\n  age            Int\n  gender         Gender\n  genderIdentity String? // Free text for non-binary identification\n  sexuality      String // \"Straight\", \"Bisexual\", \"Pansexual\", \"Queer\", \"Lesbian\", \"Gay\", \"Fluid\", etc.\n  bio            String?\n  avatar         String? // Upload URL\n  avatarType     String? // \"photo\" | \"cartoon\"\n  galleryPhotos  String  @default(\"[]\") // JSON: string[] - User photo album URLs\n  city           String?\n  country        String? @default(\"US\")\n\n  // Relationship Blueprint (核心差异化数据)\n  relationshipGoal      RelationshipGoal @default(LONG_TERM)\n  attachmentStyle       String? // \"Secure\", \"Anxious-Preoccupied\", \"Dismissive-Avoidant\", \"Fearful-Avoidant\"\n  communicationStyle    String? // \"Direct\", \"Reflective\", \"Expressive\", \"Analytical\"\n  conflictResolution    String? // \"Collaborative\", \"Compromising\", \"Accommodating\", \"Competing\", \"Avoiding\"\n  loveLanguage          String? // \"Words of Affirmation\", \"Quality Time\", \"Physical Touch\", \"Acts of Service\", \"Gifts\"\n  boundaries            String? // JSON array of boundary descriptions\n  dealbreakers          String? // JSON array\n  lifePriorities        String? // JSON array: \"Career\", \"Family\", \"Adventure\", \"Stability\", etc.\n  emotionalAvailability String? // \"Fully Available\", \"Building Trust\", \"Processing Past\", \"Needs Space\"\n\n  // ═══════════════════════════════════════════════════════════════\n  // NEW: User Preference Tags for Matching (最多5个)\n  // ═══════════════════════════════════════════════════════════════\n  selectedTags String @default(\"[]\") // JSON: string[] - 用户选择的标签\n\n  // ═══════════════════════════════════════════════════════════════\n  // PHASE B: Kink & Power Dynamics Profile\n  // ═══════════════════════════════════════════════════════════════\n  domSubRole          DomSubRole? // User's primary role identity\n  preferredRole       DomSubRole? // Preferred role in a partner\n  kinkExperienceLevel KinkExperienceLevel? // Experience level in kink dynamics\n  kinkInterests       String               @default(\"[]\") // JSON: string[] - selected kink categories\n  hardLimits          String               @default(\"[]\") // JSON: string[] - absolute boundaries\n\n  // Preferences for matching\n  preferredAgeMin   Int?\n  preferredAgeMax   Int?\n  preferredGender   String?\n  preferredDistance Int? // Max distance in miles\n  preferredLocation String?\n\n  // Matching score cache (denormalized for performance)\n  compatibilityScore Int? // 0-100 overall score\n\n  // Status\n  profileStatus  ProfileStatus @default(DRAFT)\n  onboardingStep Int           @default(0) // 0-5, tracks onboarding progress\n  isApproved     Boolean       @default(false)\n  isVerified     Boolean       @default(false)\n\n  // Personality & Matching Data (for bot users)\n  personalityData String? // 完整人格数据存储（JSON字符串）\n\n  // Admin notes\n  adminNotes String?\n\n  // Bot System Relation\n\n  // ═══════════════════════════════════════════════════════════════\n  // PRODUCT OPTIMIZATION: Elite Power Features\n  // ═══════════════════════════════════════════════════════════════\n\n  // Professional Info\n  occupation        String? // Job title\n  company           String? // Company name\n  industry          String? // Industry sector\n  linkedInVerified  Boolean @default(false)\n  verificationBadge String? // \"VERIFIED\", \"ELITE\", etc.\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([gender])\n  @@index([relationshipGoal])\n  @@index([profileStatus])\n  @@index([compatibilityScore])\n  @@index([linkedInVerified])\n  @@index([gender, profileStatus])\n  @@index([isApproved])\n  @@index([attachmentStyle]) // BUG-02 FIX: Discover API 过滤加速\n  @@index([city]) // BUG-02 FIX: Discover API 城市过滤加速\n  // Discover API 加速索引\n  @@index([onboardingStep]) // P0: Discover/AutoMatch 核心过滤字段\n  @@index([age]) // P0: 年龄范围查询\n  @@index([onboardingStep, gender]) // P0: 复合过滤 (step>=N + gender=G)\n  @@index([gender, age]) // P1: 先 gender 精确匹配再 age 范围查询\n}\n\n// ═══════════════════════════════════════════════════════════════\n// MATCHING ENGINE — Core differentiation\n// ═══════════════════════════════════════════════════════════════\n\nmodel Match {\n  id String @id @default(cuid())\n\n  // Participants\n  senderId   String\n  sender     User   @relation(\"SentMatches\", fields: [senderId], references: [id])\n  receiverId String\n  receiver   User   @relation(\"ReceivedMatches\", fields: [receiverId], references: [id])\n\n  // Matching Data\n  matchScore       Float // 0-100 compatibility score\n  matchReason      String // AI-generated explanation\n  conflictWarnings String? // JSON array of potential conflicts\n\n  // Compatibility breakdown (denormalized)\n  attachmentCompat    Float? // 0-100\n  communicationCompat Float? // 0-100\n  conflictCompat      Float? // 0-100\n  valuesCompat        Float? // 0-100\n  lifestyleCompat     Float? // 0-100\n\n  // Status\n  status    MatchStatus @default(PENDING)\n  matchType MatchType   @default(WEEKLY)\n\n  // Reaction tracking\n  matchReactions MatchReaction[]\n  senderAction   MatchAction?\n  receiverAction MatchAction?\n\n  // Connection\n  // P1-6 阶段 5：原 `chatRoom ChatRoom?` 关系随 ChatRoom 表删除而移除。\n  // 会话入口改由 Conversation.matchId 反查（见 api/matches/[id]/route.ts）。\n\n  // Admin\n  reviewedBy  String?\n  reviewNotes String?\n\n  // ═══════════════════════════════════════════════════════════════\n  // PRODUCT OPTIMIZATION: Elite Power Features\n  // ═══════════════════════════════════════════════════════════════\n\n  // Pitch Message (申请信)\n  pitchMessage String? // 50-200字申请信\n  pitchTone    String? // \"casual\", \"sincere\", \"playful\", \"direct\"\n  aiAssisted   Boolean @default(false) // 是否使用AI辅助\n\n  // Sincerity Gift (诚意值附赠)\n  giftAmount Int @default(0) // 附赠诚意值数量\n\n  // Inbox Management (收件箱管理)\n  isUnread      Boolean @default(true) // 是否未读\n  inboxPriority Float? // 收件箱排序权重 (计算值)\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  expiresAt DateTime? // Auto-expire after 7 days if not acted on\n\n  // Soft delete (v3.0)\n  deletedAt DateTime?\n\n  @@unique([senderId, receiverId], map: \"unique_match_pair\")\n  @@index([status])\n  @@index([matchScore])\n  @@index([matchType])\n  @@index([createdAt])\n  @@index([expiresAt])\n  @@index([senderId])\n  @@index([receiverId])\n  @@index([senderId, receiverId])\n  @@index([receiverId, senderId]) // P2: OR 反向查询优化\n  @@index([isUnread])\n  @@index([inboxPriority])\n  @@index([deletedAt])\n}\n\nmodel MatchReaction {\n  id      String @id @default(cuid())\n  matchId String\n  match   Match  @relation(fields: [matchId], references: [id], onDelete: Cascade)\n  userId  String\n  user    User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  reaction MatchAction\n  feedback String? // Optional feedback on why\n\n  createdAt DateTime @default(now())\n\n  @@unique([matchId, userId])\n  @@index([userId])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// P1-6 阶段 5（2026-09-28）：Legacy 三表 ChatRoom / ChatRoomMember / Message\n// 已从 schema 与数据库删除。血缘 126/126 已迁移至 IMMessage，门禁 GO。\n// 历史与执行手册：docs/CHAT-MERGE-RUNBOOK.md · docs/CHAT-MERGE-AUDIT.md\n// ═══════════════════════════════════════════════════════════════\n\n// ═══════════════════════════════════════════════════════════════\n// IM MODULE — Next-Gen Chat Infrastructure\n// ═══════════════════════════════════════════════════════════════\n\n// Conversation — logical session layer\nmodel Conversation {\n  id String @id @default(cuid())\n\n  // Participants\n  userAId     String\n  userA       User   @relation(\"ConversationUserA\", fields: [userAId], references: [id])\n  userBId     String\n  userB       User   @relation(\"ConversationUserB\", fields: [userBId], references: [id])\n  initiatorId String // who started the conversation\n\n  // Backlink to ChatRoom (migration bridge)\n  //\n  // ⚠️ 阶段 5 的 schema 编辑必须**保留 chatRoomId 标量列与唯一索引**，只删掉\n  //    `chatRoom` 关系字段（关系指向的 ChatRoom model 会被删除）。\n  //    原因：改造前 user 收藏的 /dashboard/chats/<ChatRoom.id> 旧链接里没有\n  //    Conversation.id，只能靠本列反查 —— 删掉它等于把老用户挡在\"会话不存在\"之外（G-8）。\n  //    `lib/im/resolve.ts` 的路径 2 就建立在本列的 @unique 索引上。\n  chatRoomId String? @unique\n  // P1-6 阶段 5：原 `chatRoom ChatRoom? @relation(...)` 关系随 ChatRoom 表删除而移除。\n  // 标量列 chatRoomId 与 @unique 索引**刻意保留**（G-8 旧书签别名回退，\n  // 见 lib/im/resolve.ts 路径 2）。数据库侧同步删掉了本列的外键约束。\n\n  // ═══════════════════════════════════════════════════════════════\n  // 匹配关联（G-10，阶段 5 前置修复）\n  //\n  // 发现路径：阶段 5 的 schema 清理清单原本只列了 Vault 字段。核对 `ChatRoom` 模型时\n  // 发现 `matchId` / `match.matchScore` **只存在于 ChatRoom**，而会话列表（`lib/im/list.ts`）\n  // 与会话详情都在向 UI 输出 matchScore —— 删表会让\"匹配分\"整块消失，属静默功能回退。\n  //\n  // 这里刻意**只加标量列、不加 relation**：relation 会要求 Match 侧反向声明字段，\n  // 扩大 schema 改动面；而 matchScore 只需要一次批量查询即可补齐（见 list.ts）。\n  // ═══════════════════════════════════════════════════════════════\n  matchId String?\n\n  // State\n  state       ConversationState @default(ACTIVE)\n  stateReason String? // reason for state change\n\n  // Female Control\n  controllingUserId     String? // who has control (usually female)\n  activeBoundaryVersion String? // current Power Board version\n\n  // Statistics (denormalized for performance)\n  lastMessageAt DateTime?\n  messageCount  Int       @default(0)\n  unreadCountA  Int       @default(0)\n  unreadCountB  Int       @default(0)\n\n  // Per-user settings (JSON for flexibility)\n  settings String? // JSON: { userA: {muted, pinned}, userB: {muted, pinned} }\n\n  // ═══════════════════════════════════════════════════════════════\n  // Vault —— 24h 限时对话\n  //\n  // P1-6 阶段 4（G-1 修复）：以下字段此前**只存在于 ChatRoom**。方案 A 确定 Conversation\n  // 为终局模型后，若不在删除 ChatRoom 前把它们迁移过来，阶段 5 会**整体丢失**：\n  //   · 女性用户的「终结对话」权限（vaultStatus / revokedAt / revokeReason）\n  //   · 24h 倒计时的延长审计（extensionCount / extendedAt / extendedBy）\n  //   · 截图防护的计数与取证（screenshotCount / lastScreenshotAt）\n  // 迁移脚本见 scripts/chat-merge/migrate-vault.ts（幂等 + dry-run）。\n  // ═══════════════════════════════════════════════════════════════\n\n  // Vault expiry timestamp (null = no Vault)\n  vaultExpiresAt DateTime?\n\n  // Vault 四态：ACTIVE / EXTENDED（已延长）/ REVOKED（被女性终止）/ EXPIRED（超时）\n  vaultStatus VaultStatus @default(ACTIVE)\n\n  // 延长审计\n  extensionCount Int       @default(0)\n  extendedAt     DateTime?\n  extendedBy     String?\n\n  // 女性特权：终止对话\n  revokedAt    DateTime?\n  revokedBy    String?\n  revokeReason String?\n\n  // 隐私防护\n  screenshotCount  Int       @default(0)\n  lastScreenshotAt DateTime?\n\n  // Consent cache\n  cachedConsentState ConsentState @default(CONSENT_NONE)\n\n  // Relations\n  participants    ConversationParticipant[]\n  imMessages      IMMessage[]\n  receipts        MessageReceipt[]\n  consentRequests ConsentRequest[]\n  consentGrants   ConsentGrant[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Soft delete (v3.0)\n  deletedAt DateTime?\n\n  @@unique([userAId, userBId], map: \"unique_conversation_pair\")\n  @@index([state])\n  @@index([lastMessageAt])\n  @@index([userAId])\n  @@index([userBId])\n  @@index([controllingUserId])\n  @@index([vaultExpiresAt])\n  // P1-6 阶段 4（G-1）：Vault 状态查询索引（与 ChatRoom 侧保持一致）\n  @@index([vaultStatus])\n  // P1-6 阶段 5（G-10）：匹配分补迁后按 matchId 反查\n  @@index([matchId])\n  @@index([deletedAt])\n}\n\n// ConversationParticipant — per-user conversation membership & state\nmodel ConversationParticipant {\n  id             String       @id @default(cuid())\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  userId         String\n  user           User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Per-user state\n  isMuted     Boolean   @default(false)\n  isPinned    Boolean   @default(false)\n  isArchived  Boolean   @default(false)\n  lastReadSeq Int       @default(0) // last read sequence number\n  lastReadAt  DateTime?\n\n  // Subscription\n  subscribedAt DateTime @default(now())\n\n  @@unique([conversationId, userId])\n  @@index([userId])\n  @@index([userId, isMuted])\n  @@index([userId, isPinned])\n}\n\n// IMMessage — next-gen message model\nmodel IMMessage {\n  id             String       @id @default(cuid())\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  // Core fields\n  clientMsgId String? @unique // client-generated ID for dedup\n\n  // P1-6 阶段 3 迁移桥：指向被迁移的 Legacy Message.id。\n  // 幂等锚点 —— 迁移脚本以此字段判定\"已迁/未迁\"，绝不重复插入。\n  // 阶段 5（Legacy 表删除后）可安全移除本字段。\n  legacyMessageId String? @unique\n\n  senderId   String\n  sender     User   @relation(\"IMMessageSender\", fields: [senderId], references: [id])\n  receiverId String\n  seq        Int // server-assigned sequence number (monotonic per conversation)\n\n  // Content\n  msgType  IMMessageType @default(TEXT)\n  payload  String // message content (plaintext or E2EE ciphertext)\n  metadata String? // JSON: media info, links, etc.\n\n  // Encryption\n  encryptionMode     EncryptionMode @default(SERVER)\n  ephemeralPublicKey String? // for E2EE key exchange\n\n  // Boundary & compliance\n  boundaryVersion String? // current Power Board version\n  complianceTags  String           @default(\"[]\") // JSON: string[] - [\"consent_granted\", \"media_level_2\", \"pace_ok\"]\n  consentState    ConsentState     @default(CONSENT_NONE)\n  mediaLevel      MediaAccessLevel @default(L0_TEXT)\n  ruleResult      RuleEngineResult @default(PASS)\n\n  // Reply\n  replyToMsgId   String?\n  replyToPreview String? // JSON: {msgId, senderId, previewText, mediaLevel}\n\n  // Edit & Delete\n  isEdited  Boolean   @default(false)\n  editedAt  DateTime?\n  isDeleted Boolean   @default(false)\n  deletedAt DateTime?\n  deletedBy String? // who deleted (sender or admin)\n\n  // Media metadata\n  mediaMetadata String? // JSON: {mediaId, level, mimeType, sizeBytes, width, height, durationMs, thumbnailUrl, watermarkHash, isExpiring, expiresAt}\n\n  // Delivery status\n  status MessageDeliveryStatus @default(SENT)\n\n  // Receipts\n  receipts MessageReceipt[]\n\n  // Reactions\n  reactions MessageReaction[]\n\n  createdAt DateTime @default(now())\n\n  @@index([conversationId, seq])\n  @@index([conversationId, createdAt])\n  @@index([senderId])\n  @@index([receiverId])\n  @@index([clientMsgId])\n  @@index([createdAt])\n  @@index([msgType])\n  @@index([isDeleted])\n}\n\n// MessageReceipt — per-recipient delivery & read receipts\nmodel MessageReceipt {\n  id             String       @id @default(cuid())\n  messageId      String\n  message        IMMessage    @relation(fields: [messageId], references: [id], onDelete: Cascade)\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  userId         String // who this receipt belongs to\n  user           User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Receipt state\n  deliveredAt DateTime? // when message was delivered to this user\n  readAt      DateTime? // when message was read by this user\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([messageId, userId])\n  @@index([userId, readAt])\n  @@index([conversationId])\n}\n\n// MessageReaction — emoji reactions on messages\nmodel MessageReaction {\n  id        String    @id @default(cuid())\n  messageId String\n  message   IMMessage @relation(fields: [messageId], references: [id], onDelete: Cascade)\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Emoji character\n  emoji String\n\n  createdAt DateTime @default(now())\n\n  // Each user can only add one reaction per emoji per message\n  @@unique([messageId, userId, emoji])\n  @@index([messageId])\n  @@index([userId])\n}\n\n// UserPresence — online/offline status tracking\nmodel UserPresence {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Presence state\n  status        PresenceStatus @default(OFFLINE)\n  statusMessage String? // custom status text\n  lastSeenAt    DateTime? // last heartbeat / activity timestamp\n\n  // Device info\n  deviceId   String? // current active device\n  platform   String? // \"ios\", \"android\", \"web\"\n  appVersion String? // client version\n\n  // Connection\n  connectionId String? // WebSocket connection ID\n  connectedAt  DateTime? // when current session started\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n  @@index([lastSeenAt])\n  @@index([userId, status])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// CONSENT MANAGEMENT — Granular permission control\n// ═══════════════════════════════════════════════════════════════\n\nmodel ConsentRequest {\n  id             String       @id @default(cuid())\n  requesterId    String\n  requester      User         @relation(\"ConsentRequester\", fields: [requesterId], references: [id])\n  targetId       String\n  target         User         @relation(\"ConsentTarget\", fields: [targetId], references: [id])\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  // Request details\n  consentType    ConsentRequestType @default(MEDIA)\n  requestedLevel MediaAccessLevel   @default(L0_TEXT)\n  contextMsgId   String? // message that triggered this request\n  reason         String? // user-visible reason\n\n  // Preview (encrypted)\n  previewPayload String? // encrypted preview content\n\n  // State\n  state        ConsentState @default(CONSENT_PENDING)\n  respondedAt  DateTime?\n  responseNote String?\n  grantToken   String?      @unique // authorization token for verification\n\n  // Validity\n  expiresAt DateTime\n\n  createdAt DateTime @default(now())\n\n  @@index([requesterId])\n  @@index([targetId])\n  @@index([conversationId])\n  @@index([state])\n  @@index([expiresAt])\n  @@index([consentType])\n}\n\nmodel ConsentGrant {\n  id             String       @id @default(cuid())\n  granterId      String\n  granter        User         @relation(\"ConsentGranter\", fields: [granterId], references: [id])\n  granteeId      String\n  grantee        User         @relation(\"ConsentGrantee\", fields: [granteeId], references: [id])\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  // Grant details\n  consentType  ConsentRequestType @default(MEDIA)\n  grantedLevel MediaAccessLevel   @default(L0_TEXT)\n\n  // Validity\n  grantedAt DateTime  @default(now())\n  expiresAt DateTime? // null = permanent\n\n  // Revocation\n  isRevoked Boolean   @default(false)\n  revokedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([granterId])\n  @@index([granteeId])\n  @@index([conversationId])\n  @@index([consentType])\n  @@index([isRevoked])\n  @@index([expiresAt])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// V25.6 UX06 — AI PROCESSING CONSENT (server-issued, purpose-bound)\n// ═══════════════════════════════════════════════════════════════\n// 与媒体 ConsentGrant 刻意分离：媒体授权回答\"你能否看到我的图片/语音\"，\n// 本表回答\"能否把我的原文送给远端模型、用于哪种用途、送到哪个接收范围\"。\n// consentRef 必须由服务端 /api/im/ai-consent 签发；客户端字符串一律不采信。\n// 纯标量字段（不挂 User/Conversation relation）：身份来自 auth session，\n// 校验按字符串精确比对，避免为一张授权表改动核心 model 的关系网。\nmodel AIProcessingConsent {\n  id                 String    @id @default(cuid())\n  userId             String // 数据主体（授权人，= auth session user）\n  conversationId     String\n  purpose            String // translate | expression | reply_draft\n  recipientScope     String // 允许的接收范围（会话 id / 对方标识）\n  processingLocation String    @default(\"cloud\") // cloud | local\n  modelScope         String? // null=不限定模型；否则允许的 model id\n  status             String    @default(\"ACTIVE\") // ACTIVE | REVOKED | EXPIRED\n  requestId          String? // 端到端追踪\n  grantedAt          DateTime  @default(now())\n  expiresAt          DateTime\n  revokedAt          DateTime?\n  createdAt          DateTime  @default(now())\n  updatedAt          DateTime  @updatedAt\n\n  @@index([userId, status])\n  @@index([conversationId])\n  @@index([expiresAt])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// POWER BOARD — Rule engine for boundary control\n// ═══════════════════════════════════════════════════════════════\n\nmodel PowerBoardRule {\n  id     String @id @default(cuid())\n  userId String @unique // each user has one active rule set\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Version control\n  version  String  @default(\"1.0.0\") // semantic versioning\n  isActive Boolean @default(true)\n\n  // Pace Control (JSON)\n  paceConfig String // JSON: {maxMessagesPerHour, maxMessagesPerDay, responseWindowHours, enforceCooldown, cooldownMinutes, showRemainingQuota}\n\n  // Media Policy (JSON)\n  mediaConfig String // JSON: {defaultLevel, perUserOverride, requireConsentForUpgrade, autoBlurImages, watermarkAllMedia}\n\n  // Content Filter (JSON)\n  filterConfig String // JSON: {blockedKeywords, blockedPatterns, blockExplicitImages, autoFlagProfanity, blockUnsolicitedContact, sensitivityLevel}\n\n  // Auto Response (JSON)\n  autoResponse String? // JSON: {enabled, messageTemplate, triggerAfterHours, onlyFirstMessage}\n\n  // Privacy Settings (JSON)\n  privacyConfig String // JSON: {preferredEncryption, allowScreenshotNotifications, autoExpireMessages, expireAfterDays, hideOnlineStatus, hideReadReceipts}\n\n  // Notification Preferences (JSON)\n  notifConfig String? // JSON: {pushEnabled, soundEnabled, previewEnabled, quietHoursEnabled, quietHoursStart, quietHoursEnd}\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n  @@index([version])\n  @@index([isActive])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// AUDIT LOG — Immutable audit trail with hash chain\n// ═══════════════════════════════════════════════════════════════\n\nmodel AuditLog {\n  id             String  @id @default(cuid())\n  userId         String // who this log belongs to\n  user           User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  conversationId String? // related conversation\n\n  // Action details\n  action   String // \"boundary_changed\", \"consent_granted\", \"message_blocked\", \"rule_violation\", \"security_event\"\n  actorId  String? // who performed the action\n  targetId String? // who was affected\n\n  // Details (JSON - varies by action type)\n  details String? // JSON with full context\n\n  // Hash chain (tamper detection)\n  prevHash  String? // hash of previous entry\n  entryHash String // hash of this entry\n\n  // Metadata\n  ipAddress String?\n  userAgent String?\n  deviceId  String?\n\n  createdAt DateTime @default(now())\n\n  @@index([userId, createdAt])\n  @@index([conversationId])\n  @@index([action])\n  @@index([actorId])\n  @@index([createdAt])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// NOTIFICATIONS\n// ═══════════════════════════════════════════════════════════════\n\nmodel Notification {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  type      NotificationType\n  title     String\n  body      String\n  data      String? // JSON payload for deep links\n  actionUrl String?\n\n  isRead Boolean   @default(false)\n  readAt DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@index([userId, isRead, createdAt])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// PAYMENTS & SUBSCRIPTIONS\n// ═══════════════════════════════════════════════════════════════\n\nmodel Subscription {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  plan   SubscriptionPlan\n  status SubscriptionStatus @default(ACTIVE)\n\n  // Stripe\n  stripeCustomerId       String?   @unique\n  stripePriceId          String?\n  stripeSubscriptionId   String?   @unique\n  stripeCurrentPeriodEnd DateTime?\n\n  // Matching perks\n  weeklyMatchLimit   Int     @default(5)\n  canInitiateChat    Boolean @default(true)\n  canViewFullProfile Boolean @default(true)\n\n  startsAt    DateTime  @default(now())\n  endsAt      DateTime?\n  cancelledAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Soft delete (v3.0)\n  deletedAt DateTime?\n\n  @@index([userId])\n  @@index([status])\n  @@index([deletedAt])\n  @@index([userId, status])\n}\n\nmodel Payment {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  stripePaymentIntentId String?       @unique\n  amount                Float // In USD\n  currency              String        @default(\"usd\")\n  status                PaymentStatus @default(PENDING)\n\n  description String?\n  metadata    String? // JSON\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Soft delete (v3.0)\n  deletedAt DateTime?\n\n  @@index([userId])\n  @@index([deletedAt])\n  @@index([createdAt, status])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// ADMIN & ANALYTICS\n// ═══════════════════════════════════════════════════════════════\n\n// 统一管理审计日志 (v3.0: 合并 AdminLog + AdminRoleAudit)\nmodel AdminAudit {\n  id String @id @default(cuid())\n\n  // 操作者\n  actorId String\n  actor   User   @relation(\"AdminAuditActor\", fields: [actorId], references: [id])\n\n  // 分类\n  category AuditCategory // \"user\" | \"match\" | \"payment\" | \"rbac\" | \"system\" | ...\n\n  // 操作\n  action String // \"create\" | \"update\" | \"delete\" | \"ban\" | \"grant_role\" | ...\n\n  // 目标对象\n  targetType String? // \"User\" | \"Match\" | \"Payment\" | \"AdminRole\" | ...\n  targetId   String? // 目标记录 ID\n\n  // 变更内容\n  changes String? // JSON: { before: {...}, after: {...} }\n  details String? // 额外上下文\n\n  // 原因（RBAC 变更等需要理由的操作）\n  reason String?\n\n  // 元数据\n  ipAddress String?\n  userAgent String?\n\n  createdAt DateTime @default(now())\n\n  @@index([actorId])\n  @@index([category, createdAt])\n  @@index([action])\n  @@index([targetType, targetId])\n  @@index([createdAt])\n}\n\n// 审计分类枚举 (v3.0)\nenum AuditCategory {\n  USER\n  MATCH\n  CHAT\n  PAYMENT\n  CONTENT\n  BOT\n  AI_CREATIVE\n  AI_SUPPORT\n  VIP\n  ANALYTICS\n  SYSTEM\n  RBAC\n}\n\nmodel AnalyticsEvent {\n  id     String  @id @default(cuid())\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  event         String // \"user.registered\", \"swipe.right\", \"message.sent\", etc.\n  eventCategory String  @default(\"\") // \"user\"|\"match\"|\"chat\"|\"revenue\"|\"admin\"\n  properties    String? // JSON with event data\n\n  sessionId  String?\n  deviceId   String  @default(\"\") // device fingerprint\n  pagePath   String  @default(\"\") // page path\n  platform   String  @default(\"web\") // web|ios|android\n  appVersion String  @default(\"\") // app version\n\n  ipAddress String?\n  country   String? // GeoIP country\n  city      String? // GeoIP city\n\n  // UTM tracking\n  utmSource   String?\n  utmMedium   String?\n  utmCampaign String?\n  utmContent  String?\n  utmTerm     String?\n\n  createdAt DateTime @default(now())\n\n  @@index([userId, event, createdAt])\n  @@index([event, createdAt])\n  @@index([eventCategory, createdAt])\n  @@index([sessionId])\n  @@index([createdAt])\n}\n\nmodel SystemConfig {\n  key         String   @id\n  value       String\n  description String?\n  updatedAt   DateTime @updatedAt\n  updatedBy   String?\n}\n\n// ═══════════════════════════════════════════════════════════════\n// RBAC — Role-Based Access Control (管理后台权限系统)\n// ═══════════════════════════════════════════════════════════════\n\n// 管理员角色枚举\nenum AdminRole {\n  SUPER_ADMIN // 超级管理员：全部权限，可管理其他管理员和角色\n  ADMIN // 管理员：用户/匹配/内容/支付全管理\n  MODERATOR // 审核员：举报审核/内容审核/用户封禁\n  ANALYST // 分析师：只读数据分析，可导出\n  SUPPORT // 客服：用户查看+基础操作，举报处理\n  CREATIVE // 创意运营：AI推广图全管理\n  VIP_AGENT // VIP客服：VIP收件箱专属\n}\n\n// 权限分类\nenum PermissionCategory {\n  USER // 用户管理\n  MATCHING // 匹配管理\n  CHAT // 聊天管理\n  PAYMENT // 支付管理\n  CONTENT // 内容审核\n  AI_CREATIVE // AI推广图\n  AI_SUPPORT // AI客服\n  VIP // VIP管理\n  ANALYTICS // 数据分析\n  SYSTEM // 系统配置\n  RBAC // 权限管理\n  BOT // Bot系统\n}\n\n// 单个权限定义\nmodel AdminPermission {\n  id          String             @id @default(cuid())\n  code        String             @unique // \"user.view\", \"user.ban\", \"payment.refund\"\n  name        String // \"查看用户\", \"封禁用户\", \"退款操作\"\n  description String?\n  category    PermissionCategory\n\n  // 元数据\n  isActive    Boolean  @default(true)\n  isDangerous Boolean  @default(false) // 高危权限（如删除/退款）需二次确认\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // 关联\n  rolePermissions AdminRolePermission[]\n\n  @@index([category])\n  @@index([isActive])\n}\n\n// 自定义角色 — 管理员可在 UI 中动态创建（v3.0+）\nmodel CustomRole {\n  id          String   @id @default(cuid())\n  name        String   @unique\n  description String?\n  isSystem    Boolean  @default(false) // 系统角色不可删除\n  permissions String // JSON数组: '[\"user.view\",\"user.ban\",...]'（SQLite不支持原生数组）\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  userRoles AdminUserRole[]\n\n  @@index([isSystem])\n}\n\n// 角色-权限关联（多对多）\nmodel AdminRolePermission {\n  id           String          @id @default(cuid())\n  role         AdminRole\n  permissionId String\n  permission   AdminPermission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n\n  grantedAt DateTime @default(now())\n  grantedBy String? // 授权人ID\n\n  // 复合唯一约束\n  @@unique([role, permissionId])\n  @@index([role])\n}\n\n// 管理员-角色关联（多对多：一个管理员可有多个角色）\nmodel AdminUserRole {\n  id String @id @default(cuid())\n\n  // 关联到 User 表（复用现有 User 模型）\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  role AdminRole\n\n  // 自定义角色扩展（v3.0+）：可选，叠加在系统角色之上\n  customRoleId String?\n  customRole   CustomRole? @relation(fields: [customRoleId], references: [id])\n\n  // 管理员扩展信息\n  department String? // \"operations\", \"safety\", \"growth\", \"creative\", \"vip\", \"finance\"\n  title      String? // \"运营经理\", \"客服主管\"\n  isActive   Boolean @default(true)\n\n  // 时间\n  grantedAt DateTime  @default(now())\n  grantedBy String? // 授权人ID\n  expiresAt DateTime? // 过期时间（可选，用于临时权限）\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, role])\n  @@index([userId])\n  @@index([role])\n}\n\n// AdminRoleAudit 已合并到 AdminAudit (v3.0)\n\n// ═══════════════════════════════════════════════════════════════\n// ENUMS\n// ═══════════════════════════════════════════════════════════════\n\nenum UserRole {\n  USER\n  ADMIN\n  SUPER_ADMIN\n}\n\n// ═══════════════════════════════════════════════════════════════\n// PHASE B: Expanded Identity & Relationship Enums\n// ═══════════════════════════════════════════════════════════════\n\nenum Gender {\n  // Core identities\n  MAN\n  WOMAN\n  NON_BINARY\n  // Trans identities\n  TRANSGENDER_MAN\n  TRANSGENDER_WOMAN\n  // Non-binary spectrum\n  GENDERQUEER\n  GENDERFLUID\n  AGENDER\n  BIGENDER\n  PANGENDER\n  ANDROGYNE\n  DEMIGENDER\n  NEUTROIS\n  TWO_SPIRIT\n  // Self-discovery\n  QUESTIONING\n  GENDER_NONCONFORMING\n  // Fallbacks\n  OTHER\n  PREFER_NOT_TO_SAY\n  // Legacy (backward compat)\n  MALE\n  FEMALE\n}\n\nenum DomSubRole {\n  // Core power dynamics\n  DOMINANT\n  SUBMISSIVE\n  SWITCH\n  // Positional\n  TOP\n  BOTTOM\n  // Specialized dynamics\n  BRAT\n  BRAT_TAMER\n  PRIMAL\n  RIGGER\n  ROPE_BUNNY\n  OWNER\n  PET\n  SADIST\n  MASOCHIST\n  DADDY_MOMMY\n  LITTLE\n  MASTEX\n  // Vanilla & exploring\n  VANILLA\n  EXPLORING\n  PREFER_NOT_TO_SAY\n}\n\nenum KinkExperienceLevel {\n  BEGINNER\n  INTERMEDIATE\n  EXPERIENCED\n  EXPERT\n  PREFER_NOT_TO_SAY\n}\n\nenum RelationshipGoal {\n  // v3 onboarding standard values\n  MONOGAMY // One & Only — committed exclusive connection\n  ETHICAL_NON_MONOGAMY // Open Hearts — multiple connections, honest boundaries\n  POLYAMORY // Many Loves — multiple meaningful relationships\n  CASUAL_DATING // Go With Flow — no labels, see where it goes\n  FRIENDSHIP_FIRST // Friends First — connection before romance\n  KINK_BDSM // Power Play — exploring dynamics & desires\n  // Legacy values (kept for backward compat)\n  LONG_TERM\n  DATING\n  FRIENDSHIP\n  NOT_SURE\n}\n\nenum ProfileStatus {\n  DRAFT // Onboarding in progress\n  PENDING_REVIEW // Submitted, waiting for admin review\n  APPROVED // Ready for matching\n  REJECTED // Needs revision\n  DEACTIVATED // User deactivated\n  BANNED // Admin banned\n}\n\nenum MatchStatus {\n  PENDING // Created, waiting for reactions\n  ACCEPTED // Both accepted\n  REJECTED // One or both rejected\n  EXPIRED // Not acted upon within timeframe\n  CANCELLED // Admin cancelled\n}\n\nenum MatchType {\n  WEEKLY // Regular weekly match\n  BOOSTED // Premium priority match\n  MANUAL // Admin-curated match\n  AI_SUGGESTED // AI recommendation (requires approval)\n}\n\nenum MatchAction {\n  INTERESTED // \"I'd like to connect\"\n  PASS // \"Not for me right now\"\n  MAYBE // \"Tell me more\"\n  BLOCK // \"Don't match me with this person\"\n  SUPER_LIKE // \"Super Like — highlight in recommendations\"\n}\n\nenum MessageType {\n  TEXT\n  IMAGE\n  SYSTEM // Auto-generated messages\n  VOICE // Future: voice notes\n}\n\n// IM Module Message Types\nenum IMMessageType {\n  TEXT\n  IMAGE\n  VOICE\n  FILE\n  SYSTEM\n  CONSENT_REQUEST\n  CONSENT_RESPONSE\n  RULE_UPDATE\n  TYPING\n  READ_RECEIPT\n}\n\nenum ConversationState {\n  ACTIVE\n  PAUSED // one party paused\n  BLOCKED\n  EXPIRED // auto-expired (e.g. Vault expired)\n  ARCHIVED\n}\n\nenum ConsentState {\n  CONSENT_NONE\n  CONSENT_PENDING\n  CONSENT_GRANTED\n  CONSENT_DENIED\n  CONSENT_EXPIRED\n}\n\nenum MediaAccessLevel {\n  L0_TEXT // text only\n  L1_IMAGE // static images\n  L2_VOICE // voice messages\n  L3_VIDEO // video / live calls\n  L4_LOCATION // location sharing\n  L5_CONTACT // contact info\n}\n\nenum RuleEngineResult {\n  PASS\n  SOFT_BLOCK // suggest adjustment, can override\n  HARD_BLOCK // forced block\n  PACE_LIMIT // rate limit\n}\n\nenum EncryptionMode {\n  E2EE // end-to-end encrypted\n  SERVER // server-readable (safety mode)\n  HYBRID // hybrid mode\n}\n\nenum MessageDeliveryStatus {\n  SENDING\n  SENT\n  DELIVERED\n  READ\n  FAILED\n}\n\nenum PresenceStatus {\n  ONLINE\n  AWAY\n  BUSY\n  OFFLINE\n}\n\nenum ConsentRequestType {\n  MEDIA\n  LOCATION\n  CONTACT\n  INTIMATE // intimate content\n}\n\nenum NotificationType {\n  NEW_MATCH\n  MATCH_ACCEPTED\n  MATCH_REJECTED\n  NEW_MESSAGE\n  WEEKLY_DIGEST\n  PROFILE_APPROVED\n  PROFILE_REJECTED\n  SUBSCRIPTION_EXPIRED\n  SYSTEM_ANNOUNCEMENT\n}\n\nenum SubscriptionPlan {\n  FREE\n  LADY_FREE\n  PREMIUM_MONTHLY\n  PREMIUM_YEARLY\n  LIFETIME\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  CANCELLED\n  EXPIRED\n  PAST_DUE\n  TRIALING\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCEEDED\n  FAILED\n  REFUNDED\n}\n\n// ═══════════════════════════════════════════════════════════════\n// PRODUCT OPTIMIZATION: Sincerity System & Vault\n// ═══════════════════════════════════════════════════════════════\n\nenum VaultStatus {\n  ACTIVE // 正常进行中\n  EXTENDED // 已延长\n  REVOKED // 被女性终止\n  EXPIRED // 时间到自动关闭\n}\n\nenum SincerityTransactionType {\n  EARN // 赚取\n  SPEND // 消费\n  RECEIVE_GIFT // 收到礼物\n  SEND_GIFT // 送出礼物\n  REFUND // 退款\n}\n\nmodel SincerityWallet {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Balance\n  balance       Int @default(0) // 当前余额\n  totalEarned   Int @default(0) // 累计获得\n  totalSpent    Int @default(0) // 累计消费\n  totalGifted   Int @default(0) // 累计送出礼物\n  totalReceived Int @default(0) // 累计收到礼物\n\n  // Tier System\n  tier         SincerityTier @default(BRONZE)\n  tierProgress Float         @default(0) // 到下一级的进度 0-100\n\n  // Stats\n  lastEarnedAt DateTime?\n  lastSpentAt  DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  transactions SincerityTransaction[]\n\n  @@index([tier])\n  @@index([balance])\n}\n\nmodel SincerityTransaction {\n  id       String          @id @default(cuid())\n  walletId String\n  wallet   SincerityWallet @relation(fields: [walletId], references: [id], onDelete: Cascade)\n\n  // Transaction Details\n  type   SincerityTransactionType\n  amount Int\n\n  // Source/Reason\n  source      String // \"PROFILE_COMPLETE\", \"DAILY_LOGIN\", \"MATCH_ACCEPTED\", \"PITCH_SEND\", etc.\n  description String? // 用户可见的描述\n\n  // Related Entities\n  matchId    String? // 关联的匹配\n  fromUserId String? // 送礼人\n  toUserId   String? // 收礼人\n  message    String? // 附言\n\n  // Metadata\n  metadata String? // JSON for additional data\n\n  createdAt DateTime @default(now())\n\n  @@index([walletId])\n  @@index([type])\n  @@index([createdAt])\n  @@index([source])\n}\n\nenum SincerityTier {\n  BRONZE // 0-499\n  SILVER // 500-1999\n  GOLD // 2000-4999\n  PLATINUM // 5000+\n}\n\n// ═══════════════════════════════════════════════════════════════\n// SAFETY & MODERATION — User Block List\n// ═══════════════════════════════════════════════════════════════\n\nmodel Block {\n  id        String @id @default(cuid())\n  blockerId String // User who blocks\n  blocker   User   @relation(\"BlockerRelations\", fields: [blockerId], references: [id], onDelete: Cascade)\n  blockedId String // User who is blocked\n  blocked   User   @relation(\"BlockedRelations\", fields: [blockedId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  // Prevent duplicate blocks\n  @@unique([blockerId, blockedId], name: \"unique_block_pair\")\n  @@index([blockerId])\n  @@index([blockedId])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// SAFETY & MODERATION — User Reports\n// ═══════════════════════════════════════════════════════════════\n\nenum ReportReason {\n  INAPPROPRIATE_CONTENT\n  HARASSMENT\n  FAKE_PROFILE\n  SPAM\n  OFFENSIVE_BEHAVIOR\n  OTHER\n}\n\nenum ReportStatus {\n  PENDING\n  UNDER_REVIEW\n  RESOLVED_NO_ACTION\n  RESOLVED_WARNING\n  RESOLVED_BANNED\n  DISMISSED\n}\n\nmodel UserReport {\n  id String @id @default(cuid())\n\n  // Reporter (who made the report)\n  reporterId String\n  reporter   User   @relation(\"ReportsMade\", fields: [reporterId], references: [id], onDelete: Cascade)\n\n  // Reported user (who was reported)\n  reportedUserId String\n  reportedUser   User   @relation(\"ReportsReceived\", fields: [reportedUserId], references: [id], onDelete: Cascade)\n\n  // Report details\n  reason      ReportReason\n  description String?\n\n  // Context (optional)\n  chatRoomId String?\n  messageId  String?\n\n  // Status tracking\n  status     ReportStatus @default(PENDING)\n  reviewedBy String? // Admin user ID\n  reviewedAt DateTime?\n  adminNotes String?\n\n  // Resolution\n  actionTaken String? // \"WARNING\", \"BAN\", \"NONE\", etc.\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Soft delete (v3.0)\n  deletedAt DateTime?\n\n  @@index([reporterId])\n  @@index([reportedUserId])\n  @@index([status])\n  @@index([createdAt])\n  @@index([status, createdAt])\n  @@index([deletedAt])\n  @@index([reporterId, reportedUserId, createdAt])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// ANALYTICS TRACKING — Event Definition & Aggregation\n// ═══════════════════════════════════════════════════════════════\n\nmodel AnalyticsEventDef {\n  id          String   @id @default(cuid())\n  name        String   @unique // e.g. \"user.registered\"\n  category    String // \"user\"|\"match\"|\"chat\"|\"revenue\"|\"admin\"\n  description String   @default(\"\")\n  properties  String   @default(\"{}\") // JSON Schema\n  isActive    Boolean  @default(true)\n  sampleRate  Float    @default(1.0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\nmodel AnalyticsDailyAgg {\n  id         String   @id @default(cuid())\n  date       DateTime // aggregation date\n  eventName  String // event name\n  metricName String // \"count\"|\"unique_users\"|\"avg_value\"\n  value      Float // metric value\n  dimensions String   @default(\"{}\") // JSON dimensions\n  createdAt  DateTime @default(now())\n\n  @@unique([date, eventName, metricName, dimensions])\n  @@index([date])\n  @@index([date, eventName])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// OUTCOME — T08 成果验证、成本归因与订阅\n//\n// 对齐：AC-15（自报与双方确认**分开**，不把系统猜测计为已验证）\n//       AC-16（任务成本 / 人工工时 / 介绍漏斗**可复算**）\n//       AC-21（用量可复算；退款/失败/升级/降级状态一致）\n//\n// 设计约束（继承 tenancy.prisma / connection.prisma 的同一套）：\n//   1. **纯新增** —— 本文件不改动既有模型的任何列语义，可独立上线（零停机、零回归）。\n//   2. **方言无关** —— 不含任何 `@db.*` 原生类型标注，同一份定义可同时为\n//      libSQL（当前生产）与 PostgreSQL（M6 目标）生成；差异只体现在迁移 SQL。\n//   3. **软引用优先** —— 成果与验证是**证据**，不应随被引用行级联消失\n//      （同 `WorkflowJob.proposalId` 的取向，见 connection.prisma 文件头）。\n//   4. **验证级别是派生值，不是入参** —— 见 `src/lib/outcome/verification.ts`。\n//      🔴 若允许客户端直接写 `verificationLevel`，AC-15 会在第一次越权调用时失效。\n//\n// 为什么**不**复用 core.prisma 的 `Subscription` / `Payment`：\n//   它们面向**个人 B2C**（`userId` + Stripe），而 T08 是**组织级用量计费**（`organizationId`）。\n//   混用会让「这个用户是不是会员」这条既有查询悄悄包含社群订阅 —— 最典型的污染方式。\n//   `AnalyticsEvent` 同理不复用：它是\"用户做了什么\"的行为流，不是\"业务产出了什么\"的账。\n// ═══════════════════════════════════════════════════════════════\n\n/// 成果验证级别（三级，逐级升高）。\n/// 🔴 **派生自 `OutcomeVerification` 记录集**，不是可自由设置的字段。\nenum OutcomeVerificationLevel {\n  SELF_REPORTED // 仅上报方陈述 —— 🔴 **不算验证成功**（AC-15 的字面要求）\n  COUNTERPARTY_CONFIRMED // 对手方确认\n  EXTERNALLY_VERIFIED // 外部证据核验（运营，`outcome.verify`，仅 ADMIN+）\n}\n\n/// 成果记录：一次连接（提案）的最终产出。\n///\n/// 与 `IntroductionWorkflow` 的关系：提案 1:1 绑定一份成果。\n/// `OUTCOME_RECORDED` 是阶段机终态（见 `src/lib/workflow/stage-machine.ts`），\n/// 但本表**不**强 FK 到提案 —— 见下 `proposalId` 注释。\nmodel Outcome {\n  id String @id @default(cuid())\n\n  /// 租户谓词。**不可省** —— 所有查询都必须以它为首要条件（T01 铁律）。\n  organizationId String\n\n  /// 软引用：挂载的提案。**刻意无外键** —— 成果是被删资源的证据，\n  /// 删提案不应连带抹掉\"这里曾经发生过一次成功的连接\"。\n  /// `@@unique` 保证一个提案只落一份成果（`OUTCOME_RECORDED` 是终态）。\n  proposalId String\n\n  /// 软引用：租户内筛选用（同 `IntroductionWorkflow.missionId`）。\n  missionId String\n\n  /// 软引用：上报方。**不进 DTO** —— 返回 userId 等于把\"谁跟谁连接了\"这条\n  /// 关系数据披露给任意 `outcome.read` 持有者（MEMBER 起即有）。DTO 只给角色。\n  reporterId String\n\n  /// 软引用：对手方。**不进 DTO**，同上。\n  counterpartyId String\n\n  /// 上报方的陈述（自报内容）。这是**原始事实**，不是结论 —— 它本身不能证明成功。\n  summary String\n\n  /// 🔴 **派生快照**：只由服务层依 `OutcomeVerification` 记录集写入（`deriveVerificationLevel`），\n  /// **不接受客户端入参**。默认 `SELF_REPORTED` 即\"下限\"：上报即得，但**不是**验证成功。\n  verificationLevel OutcomeVerificationLevel @default(SELF_REPORTED)\n\n  /// 成果发生时间（**业务时间**，可回填）。与 `createdAt`（系统看见的时间）刻意分开：\n  /// 成本/漏斗按时段复算时，口径必须明确取哪一个。\n  occurredAt DateTime\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  organization  Organization          @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  verifications OutcomeVerification[]\n\n  /// 一个提案只落一份成果。\n  @@unique([proposalId])\n  /// 运营视图按\"验证级别\"分桶（\"已验证 / 仅自报\"）是主查询。\n  @@index([organizationId, verificationLevel])\n  @@index([organizationId, createdAt])\n  @@index([organizationId, missionId])\n}\n\n/// 验证记录：每一次\"确认 / 核验\"是一条**不可变记录**。\n///\n/// 事件溯源：级别由**记录集**派生（`deriveVerificationLevel`），不由单条记录决定。\n/// 想撤销一次确认，就再记一条相反语义的记录，而不是**改写历史** ——\n/// 后者会让\"这条成果当时算不算数\"永远无法回溯。\nmodel OutcomeVerification {\n  id String @id @default(cuid())\n\n  organizationId String\n  outcomeId      String\n\n  /// 本条记录把级别抬到哪一档。派生时取**记录集中最高**的一档。\n  level OutcomeVerificationLevel\n\n  /// 确认 / 核验人 userId。系统核验为 null。**不进 DTO**。\n  actorId String?\n\n  /// 证据摘要（**脱敏后**落库）。**不进 DTO** —— 原文可能含 PII。\n  evidence String?\n\n  note      String?\n  createdAt DateTime @default(now())\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  /// 正向：验证记录脱离成果没有意义 → **强 FK + CASCADE**\n  /// （与 `IntroductionWorkflow.proposalId` 同取向，与 `Outcome.proposalId` 相反）。\n  outcome      Outcome      @relation(fields: [outcomeId], references: [id], onDelete: Cascade)\n\n  /// 幂等：同一人对同一成果的同一级别只算一次确认（重复提交不产生第二条记录）。\n  /// ⚠️ `actorId` 可空，而 SQL 唯一索引**不去重 NULL** —— 故系统核验（`actorId=null`）\n  /// 的幂等由服务层负责，不依赖此约束。\n  @@unique([outcomeId, level, actorId])\n  @@index([organizationId, createdAt])\n  @@index([outcomeId])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// TENANCY — T01 身份与多租户底座\n//\n// 对齐契约：contracts/schema.sql:4-14 (organizations / memberships / persons)\n// 与 schema.sql:55-59 (audit_events)。\n//\n// 设计约束（来自 MIGRATION_PLAN.md §2）：\n//   1. 加列优先（Additive-first）—— 本文件**全部为新增模型**，不改动既有 39 个模型\n//      的任何列语义，因此可先于任何数据回填独立上线，零停机、零回归。\n//   2. `User` ↔ 契约的 `persons` 同义。为避免全站重命名（P1-6 阶段已清理过一轮\n//      Legacy 命名），保持 `User` 不动，仅在语义层建立映射。\n//   3. 方言无关：本文件不包含任何 `@db.*` 原生类型标注，同一份定义可同时为\n//      libSQL（当前生产）与 PostgreSQL（M6 目标）生成；差异只体现在迁移 SQL。\n//   4. 绝不信任客户端传入的 organizationId —— 解析逻辑见 src/lib/tenancy/。\n// ═══════════════════════════════════════════════════════════════\n\n/// 租户角色。取值与 contracts/schema.sql:12 的 CHECK 约束逐字一致。\nenum MembershipRole {\n  OWNER // 租户所有者：可转让、可删除租户\n  ADMIN // 管理员：可管理成员与全部业务资源\n  OPERATOR // 运营：可创建/执行 Mission 与连接，不可管理成员\n  MEMBER // 成员：仅可操作自己的 Intent / Consent\n}\n\n/// 租户状态。\nenum OrganizationStatus {\n  ACTIVE\n  SUSPENDED // 停用：可读不可写，用于风控与欠费\n}\n\n/// 成员状态。\nenum MembershipStatus {\n  ACTIVE\n  INVITED // 已邀请未接受：不产生任何租户内权限\n  SUSPENDED // 已停用：保留数据，权限立即失效\n}\n\n/// 邀请状态。\nenum InvitationStatus {\n  PENDING // 待接受\n  ACCEPTED // 已接受（终态）\n  REVOKED // 已撤销（终态）\n  EXPIRED // 已过期（终态；惰性标记，见 invitations.ts）\n}\n\n/// 成员邀请。\n///\n/// 🔴 库里**只存 token 的哈希**，不存 token 本身。\n///    理由与密码相同：数据库泄露时，明文 token 等于一张可直接使用的入场券。\n///    因此\"重发邀请\"只能是**换一张新票**（旧 token 立即失效），不能把旧票再读出来。\nmodel OrganizationInvitation {\n  id             String           @id @default(cuid())\n  organizationId String\n  /// 被邀请人邮箱，**统一小写**存储；接受时须与会话账号一致。\n  email          String\n  role           MembershipRole   @default(MEMBER)\n  /// sha256(token) 的十六进制。唯一 —— 同一 token 不可能属于两条邀请。\n  tokenHash      String           @unique\n  status         InvitationStatus @default(PENDING)\n  /// 邀请人（软引用：用户注销后\"谁邀请的\"仍须可查，故不建 FK）。\n  invitedBy      String?\n  expiresAt      DateTime\n  acceptedAt     DateTime?\n  acceptedBy     String?\n  revokedAt      DateTime?\n  createdAt      DateTime         @default(now())\n  updatedAt      DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  /// 同一租户下按邮箱查\"有没有待接受的邀请\"是热路径（防重复邀请）。\n  @@index([organizationId, email, status])\n  @@index([organizationId, status])\n}\n\n/// 租户（组织）。对应契约 organizations 表。\nmodel Organization {\n  id        String             @id @default(cuid())\n  name      String\n  /// 对外可读标识，用于 URL 与分享页；唯一。\n  slug      String             @unique\n  status    OrganizationStatus @default(ACTIVE)\n  createdAt DateTime           @default(now())\n  updatedAt DateTime           @updatedAt\n\n  memberships Membership[]\n  auditEvents TenantAuditEvent[]\n  invitations OrganizationInvitation[]\n\n  // ── T02 Connection OS 反向关系（connection.prisma）──\n  missions              Mission[]\n  missionParticipations MissionParticipation[]\n  idempotencyRecords    IdempotencyRecord[]\n\n  // ── T03 Connection OS 反向关系（connection.prisma）──\n  socialIntents SocialIntent[]\n\n  // ── T05 Connection OS 反向关系（connection.prisma）──\n  //\n  // 注意：`ConnectionProposal` 上**同时**有 `missionId` 与 `organizationId` 两个外键，\n  // 但只有 `organizationId` 指向本模型，因此不需要额外命名关系。\n  connectionProposals ConnectionProposal[]\n  proposalDecisions   ProposalDecision[]\n\n  // ── T06 Connection OS 反向关系（connection.prisma）──\n  //\n  // ⚠️ 注意 `WorkflowJob.proposalId` / `MessageDelivery.recipientId` **不在此列**：\n  // 它们是**软引用**（无 FK），见 connection.prisma 文件头「软引用，不是外键」。\n  // 只有真正建了 FK relation 的三个模型出现在这里。\n  workflowJobs           WorkflowJob[]\n  notificationDeliveries NotificationDelivery[]\n  introductionWorkflows  IntroductionWorkflow[]\n\n  // ── T08 Connection OS 反向关系（outcome.prisma）──\n  //\n  // ⚠️ 注意 `Outcome.proposalId` / `.reporterId` / `.counterpartyId` **不在此列**：\n  // 它们是**软引用**（无 FK）—— 成果是被删资源的证据。只有 `OutcomeVerification.outcomeId`\n  // 建了真 FK（CASCADE）。\n  outcomes             Outcome[]\n  outcomeVerifications OutcomeVerification[]\n\n  // ── T08 Connection OS 反向关系（billing.prisma）──\n  //\n  // ⚠️ 注意两表里的 id 列（`UsageRecord.sourceId` / `BillingEvent.chargeId`）\n  // **不在此列**：它们是**软引用**（无 FK）—— 账是历史，删提案/删成果不该抹掉用量。\n  // 只有 `organizationId` 建了真 FK。\n  usageRecords       UsageRecord[]\n  billingEvents      BillingEvent[]\n  /// V25.5 P0.1 · R-15 Durable Inbox（验签事件收件箱，含中间态与人工复核队列）。\n  billingInboxEvents BillingInboxEvent[]\n\n  // ── T09 Agent Runtime 反向关系（agent.prisma）──\n  //\n  // ⚠️ 注意 `AgentRun.requestedBy` / `AgentApproval.actorId` **不在此列**：\n  // 它们是**软引用**（无 FK）—— 用户注销后\"谁批准过什么\"仍须可查。\n  // `AgentCall` 虽是 `AgentRun` 的子表，但它自己也带 `organizationId` 外键\n  // （本仓铁律：每条账都要能独立按租户查询），故这里仍需一条反向关系。\n  agentRuns            AgentRun[]\n  agentCalls           AgentCall[]\n  agentApprovals       AgentApproval[]\n  agentExecutions      AgentExecution[]\n  agentDeliveryTargets AgentDeliveryTarget[]\n\n  // ── T10 Community Bridge 反向关系（bridge.prisma）──\n  //\n  // ⚠️ 只列出 `BridgeMemberOptIn`。`CommunityBridge.initiatorOrgId` / `.recipientOrgId`\n  //    是**软引用**（无 FK）—— 协议是两个组织之间的**历史记录**，组织注销后仍须可查，\n  //    且组织重建后**不得**继承旧协议。故本模型上**没有**对应的反向关系字段。\n  //    这不表示\"查不到协议\"，而是\"不靠 FK 保证其完整性\"（见 bridge.prisma 约束 3）。\n  bridgeMemberOptIns BridgeMemberOptIn[]\n\n  @@index([status])\n}\n\n/// 成员关系（用户 × 租户）。对应契约 memberships 表。\n/// 契约用复合主键 (organization_id, person_id)；Prisma 用代理主键 + 唯一约束表达，\n/// 语义等价且便于后续扩展（如软删除、审计字段）。\nmodel Membership {\n  id             String           @id @default(cuid())\n  organizationId String\n  userId         String\n  role           MembershipRole   @default(MEMBER)\n  status         MembershipStatus @default(ACTIVE)\n  createdAt      DateTime         @default(now())\n  updatedAt      DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  user         User         @relation(\"UserMemberships\", fields: [userId], references: [id], onDelete: Cascade)\n\n  /// 同一租户内同一用户只能有一条成员关系。\n  @@unique([organizationId, userId])\n  /// 反查「我属于哪些租户」是每次会话建立时的热路径。\n  @@index([userId, status])\n  @@index([organizationId, role])\n}\n\n/// 租户级审计事件。对应契约 audit_events 表。\n///\n/// 与既有 `AuditLog`（core.prisma 哈希链审计）**并存**，分工如下：\n///   - `AuditLog`      ：既有产品行为的不可抵赖链（保留 prevHash/entryHash），不动。\n///   - `TenantAuditEvent`：闭环的**安全事件流**（租户/成员/授权/越权尝试），\n///                        可写 `safeMetadata`（脱敏，禁止放 PII 明文）。\n/// 收敛计划见 REUSE_MATRIX.md B5（M5 之后）。\nmodel TenantAuditEvent {\n  id             String   @id @default(cuid())\n  organizationId String\n  /// 触发者；系统触发时为 null（例如定时任务、迁移）。\n  actorId        String?\n  /// 事件类型，命名规范：`<domain>.<action>`，如 `membership.role_changed`。\n  eventType      String\n  /// 资源类型，如 `membership` / `mission` / `proposal`。\n  resourceType   String\n  resourceId     String?\n  /// 脱敏元数据（JSON 文本）。**禁止**写入密码、令牌、完整邮箱等 PII。\n  safeMetadata   String?\n  createdAt      DateTime @default(now())\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@index([organizationId, createdAt])\n  @@index([organizationId, eventType])\n  @@index([resourceType, resourceId])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// V21 · 第二批「服务端真实闭环」—— 纯新增表\n//\n// 对齐：\n//   - C04 字段级编辑持久化 + 版本 + 并发保护（MissionSpecRevision）\n//   - G09 独立成果核验（ExecutionVerification）\n//   - C03 服务端真实编排阶段事件（AgentRunStageEvent）\n//\n// 设计约束（继承同目录各 .prisma 文件的同一套）：\n//   1. **纯新增** —— 不改动任何既有模型的列语义；既有表的唯一改动是\n//      connection.prisma 里给 Mission 追加**可选**列 `sourceRunId`。\n//   2. **方言无关** —— 不含任何 `@db.*` 原生类型标注（SQLite / PG 同构）。\n//   3. **软引用，刻意不建 relation** —— 三张表都只存 `organizationId` 字符串。\n//      若给它们加 `Organization @relation(...)`，就必须在 tenancy.prisma 的\n//      `Organization` 上补反向关系字段 —— 那会改动本批次之外的既有模型，\n//      与「只做扩展、不碰其它线」相冲突。租户隔离**一律**由服务端\n//      `where: { organizationId, ... }` 谓词保证（新 API 全部过 `withTenant`）。\n//   4. **只增不改** —— 版本/核验/阶段事件都是「已发生事实」的留痕，\n//      不做 UPDATE；并发唯一性靠 `@@unique` 在库级兜底。\n// ═══════════════════════════════════════════════════════════════\n\n/// C04 · Mission 字段级编辑的**版本化**留痕。\n///\n/// 🔴 `@@unique([missionId, version])` 是并发保护的核心：两个都读到\n///    `currentVersion = N` 的请求同时写 `N+1`，第二条撞唯一键 → 409\n///    `SPEC_VERSION_CONFLICT`，而不是静默覆盖掉一次编辑。\nmodel MissionSpecRevision {\n  id             String @id @default(cuid())\n  /// 租户谓词。**不可省**（T01 铁律）。\n  organizationId String\n  missionId      String\n  version        Int\n\n  /// 经 `WorkspaceSpecSchema.safeParse` 校验后的**完整** spec（JSON 文本）。\n  specJson String\n\n  /// 从 spec 的 intent 节点投影出的业务字段（可选）：便于不解析 JSON\n  /// 就能回答「哪一版改了目标」。找不到对应节点时为 null。\n  goal            String?\n  offer           String?\n  successCriteria String?\n  expiresAt       String?\n  changeNote      String?\n\n  /// 编辑者（服务端会话派生，不采信请求体）。\n  actorId   String\n  createdAt DateTime @default(now())\n\n  @@unique([missionId, version])\n  @@index([organizationId, missionId, version])\n}\n\n/// G09 · 独立成果核验（与 AgentRun **无** Outcome 依赖，不复用 Outcome 表）。\n///\n/// 🔴 `verdict` / `verificationLevel` 由**服务端派生**，不接受客户端入参：\n///    核验的证据是真实 `AgentExecution` 回执行（deliveryId / deliveryStatus），\n///    **不是**模型输出。响应只陈述事实，不宣布目标达成。\nmodel ExecutionVerification {\n  id             String @id @default(cuid())\n  organizationId String\n  missionId      String\n  /// 被核验的运行 = `Mission.sourceRunId`（创建时已由服务端校验锚点）。\n  runId          String\n\n  /// 真实回执引用：`AgentExecution.deliveryId`（软引用）。\n  receiptRef String?\n\n  /// enum-ish 判定值（当前恒为服务端派生的 'CONFIRMED'）。\n  verdict      String\n  /// 验收判据（JSON 文本数组）：逐条 `{ label, confirmed, note? }`。\n  criteriaJson String\n  /// 人对事实的补充说明（**不是**模型输出；模型输出键在入口即被拒）。\n  evidenceNote String?\n\n  /// 第二人核验者（服务端会话派生）。**必须 !== AgentRun.requestedBy**。\n  verifierId String\n  createdAt  DateTime @default(now())\n\n  /// 一个 mission 的同一个 run 只核一次；重复提交不产生第二条。\n  @@unique([missionId, runId])\n  @@index([organizationId, missionId])\n}\n\n/// C03 · Agent 运行**编排阶段事件**。\n///\n/// ⚠️ 语义边界（必须在代码与响应里写清）：这些是**编排阶段**\n///    （QUOTA_CHECK / MODEL_CALL / SCHEMA_VALIDATE / PERSISTED / DEGRADED），\n///    **不是模型 token 流**，也不宣称模型生成过程被实时转发或可被逐字回放。\n///    每条只记录「服务端编排走到哪一步、当时的事实是什么」。\nmodel AgentRunStageEvent {\n  id             String   @id @default(cuid())\n  organizationId String\n  runId          String\n  /// 运行内序号，从 1 开始；`@@unique([runId, seq])` 保证重放不插重复行，\n  /// 也是 SSE `Last-Event-ID` 断点续传的基准。\n  seq            Int\n  stage          String\n  at             DateTime\n  /// 阶段事实（JSON 文本，脱敏后的结构性信息）。\n  detail         String?\n\n  @@unique([runId, seq])\n  @@index([organizationId, runId, seq])\n}\n"
}

